// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · İktisat düşüncesi tarihi ve iktisatçılar (orta).
const ozEconomics14Orta = <(String, String, List<String>, String)>[
  ('Aristoteles, bir ayakkabının hem giyilmek hem de başka bir malla değiştirilmek için kullanılabildiğini belirterek hangi ayrımın temelini atmıştır?', 'Kullanım değeri ile değişim değeri ayrımının', ['Sabit sermaye ile dolaşan sermaye ayrımının', 'Nominal fiyat ile reel fiyat ayrımının', 'Marjinal fayda ile toplam fayda ayrımının'], 'Aristoteles bir nesnenin hem kullanım hem değişim işlevi olduğunu belirtmiş; bu ayrım sonradan Smith ve Marx tarafından yeniden ele alınmıştır.'),
  ('Aristoteles\'in \'krematistik\' adını verdiği, para kazanmayı başlı başına amaç edinen etkinlik, ev ekonomisinden hangi bakımdan ayrılır?', 'Ev ekonomisinin aksine doğal bir doyum sınırı taşımaz', ['Ev ekonomisinden farklı olarak yalnızca devlet eliyle yürütülür', 'Ev ekonomisinden farklı olarak yalnızca takas yoluyla yapılır', 'Ev ekonomisinden farklı olarak yalnızca tarımsal üretimi kapsar'], 'Aristoteles\'e göre ev yönetimi gerçek gereksinimlerle sınırlıdır; krematistik ise servet artırmayı sınırsız bir amaç haline getirir ve bu yüzden eleştirilir.'),
  ('Atinalı yazar Xenophon\'un \'Poroi\' (Gelirler) adlı risalesinde Atina\'nın gelirini artırmak için başlıca hangi kaynağın daha verimli işletilmesi önerilmiştir?', 'Lavrion gümüş madenlerinin', ['Mısır\'dan ithal edilen tahılın', 'Girit\'teki zeytinlik arazilerin', 'Pers Körfezi ticaret yollarının'], 'Xenophon, Atina\'nın barış yoluyla zenginleşmesini istemiş; devletin köle ve yatırım sağlayarak Lavrion madenlerini genişletmesini önermiştir.'),
  ('Platon\'a göre bir kentte işbölümünün doğmasının temel nedeni aşağıdakilerden hangisidir?', 'İnsanların tek başına kendi kendine yetememesi', ['Devletin her yurttaşın hangi işi yapacağını zorunlu kılması ve üretimi denetlemesi', 'Kölelerin sayısının artması ve özgür yurttaşların çalışmaktan vazgeçmesi', 'Paranın ortaya çıkıp takas ihtiyacını tümüyle ortadan kaldırması'], 'Platon Devlet adlı eserinde, bireylerin gereksinimlerinin çokluğu ve tek başına yetememesi nedeniyle uzmanlaşma ve ticaretin doğduğunu anlatır.'),
  ('Atinalı yasa koyucu Solon\'un M.Ö. 594 dolayında çıkardığı \'seisachtheia\' düzenlemesi neyi ifade eder?', 'Borçların hafifletilmesi ve borç köleliğinin kaldırılması', ['Gümüş sikkelerin ilk kez tedavüle sokulması ve ticaretin para ile yapılması', 'Tahıl ihracatının yasaklanması ve yurt içi fiyatların sabitlenmesi', 'Gümrük vergilerinin tümüyle kaldırılması ve limanların açılması'], 'Seisachtheia \'yükün atılması\' demektir; borç yüzünden köleleşen yurttaşları özgürleştirmiş ve toprak üzerindeki borç işaretlerini kaldırmıştır.'),
  ('Platon\'un Yasalar adlı eserinde önerdiği ideal kentte yurttaşların servetine ilişkin sınır nasıl belirlenmiştir?', 'En yoksulun mülkünün birkaç katıyla sınırlandırılmıştır', ['Hiçbir sınır konmamış, serbest servet birikimi ve sınırsız mülk edinme öngörülmüştür', 'Yalnızca toprak ve altın edinmek yasaklanmış, diğer mallarda sınır konmamıştır', 'Bütün mülk devlete devredilmiş ve yurttaşlara yalnızca günlük pay verilmiştir'], 'Yasalar\'da servet, bir temel mülk payının en çok dört katıyla sınırlanır; amaç aşırı zenginlik ile yoksulluğun kent birliğini bozmasını önlemektir.'),
  ('Aristoteles\'in \'adil değişim\' için ileri sürdüğü ölçüt aşağıdakilerden hangisidir?', 'Tarafların emeğinin ve gereksiniminin oranlı karşılaştırılması', ['Devletin koyduğu en yüksek fiyatın aşılmaması ve herkesin aynı fiyata uyması', 'Satıcının kâr oranının tüm mallarda sabit tutulması ve değişmemesi', 'Alıcının sahip olduğu altın miktarına göre fiyatın belirlenmesi'], 'Nikomakhos\'a Etik\'te takas edilen malların, üreticilerin katkısıyla orantılı bir denklikte değiştirilmesi adil değişim sayılır.'),
  ('Aristoteles\'in köleliği ev ekonomisinin \'canlı aleti\' olarak görmesi, onun iktisat anlayışı için hangi sonucu doğurur?', 'Üretimde emeği yalnızca bir araç olarak görmesi', ['Ücretli emeği en verimli sayması', 'Köleliği kaldırmayı savunması', 'Ücretlerin sendikalarca belirlenmesini istemesi'], 'Aristoteles köleyi ev yönetiminde bir \'canlı mülk\' sayar; bu yaklaşım antik çağın emek anlayışını ve özgür yurttaş-köle ayrımını yansıtır.'),
  ('Arthashastra\'nın devlet ekonomisine bakışını en iyi özetleyen ifade aşağıdakilerden hangisidir?', 'Devlet vergi, fiyat ve ticaret üzerinde ayrıntılı denetim kurar', ['Devlet ekonomiye hiçbir biçimde karışmamalı, bütün kararlar tüccarlara bırakılmalıdır', 'Ticaret yasaklanmalı, ülke yalnızca tarım yaparak geçinmeli ve dışa kapanmalıdır', 'Vergiler tamamen kaldırılmalı, devlet gelirini yalnızca bağışlardan sağlamalıdır'], 'Metin, devlet gelirlerinin, madenlerin, pazarların, ağırlık ölçülerin ve fiyatların denetlendiği müdahaleci bir yönetim tarif eder.'),
  ('Thomas Aquinas, ödünç verilen paranın faizle geri alınmasını neden günah saymıştır?', 'Tüketilen bir şeyin kullanımı ile kendisini ayrı ayrı satmak, aynı şeyi iki kez satmak olur', ['Paranın hiçbir zaman değer taşımadığı, bu yüzden faiz alınmasının anlamsız olduğu için', 'Faizin yalnızca yabancılar tarafından alındığı ve yurttaşlara zarar verdiği için', 'Borçluların her zaman yoksul olduğu ve geri ödeme güçlerinin bulunmadığı için'], 'Aquinas\'a göre para tüketilir; kullanımı ile aslı birbirinden ayrılamaz, dolayısıyla ödünç para üzerinden ücret istemek haksızdır.'),
  ('Skolastik düşünürlere göre bir tüccarın kazancı hangi koşulda meşru sayılabilirdi?', 'Taşıma, emek ve risk gibi hizmetlerin karşılığı olması', ['Fiyatları tek başına belirlemesi', 'Başka tüccarları piyasadan çıkarması', 'Kıtlık sırasında stok yapıp fiyatı yükseltmesi'], 'Sienalı Bernardino gibi düşünürler tüccarın emeği, riski ve hizmetini kâr gerekçesi saymış; yalnızca fırsatçılık ya da tekelcilik haksız kabul edilmiştir.'),
  ('Üçüncü Lateran Konsili (1179), faizle borç veren kişilere yönelik hangi tutumu benimsemiştir?', 'Alenî tefecileri dinî cezalara maruz bırakmıştır', ['Faizi teşvik etmiştir', 'Yalnızca Yahudilerin faiz almasını yasaklamıştır', 'Faiz oranını yüzde ona sabitlemiştir'], 'Konsil, faizli borç verenlerin kutsal ayinlerden ve Hristiyan defninden yoksun bırakılmasını öngörmüş; faiz yasağı bu sayede kilise hukukunda pekişmiştir.'),
  ('Ebu Yusuf, toprak vergisinde sabit bir miktar yerine ürünün belli bir oranının alınması (mukasame) usulünü neden tercih etmiştir?', 'Çiftçinin ürünü azaldığında yükünün de azalması, böylece adaletli olması', ['Hazineye daha çok gelir sağlamak ve devlet hazinesini her yıl artırmak', 'Vergi memurlarının işini kolaylaştırıp toplama maliyetini azaltmak', 'Ürünlerin yıl boyunca saklanmasını sağlayıp fiyat dalgalanmasını önlemek'], 'Orantılı vergi, kuraklıkta ve verim düşüşünde vergiyi de düşürür; Ebu Yusuf bu yolla çiftçiyi koruyup üretimi sürdürmeyi amaçlamıştır.'),
  ('Gazali\'nin İhyâ-i Ulûmi\'d-Dîn adlı eserinde parayı açıklarken kullandığı fikir aşağıdakilerden hangisidir?', 'Paranın başlı başına değil, değişimi kolaylaştıran bir araç olması', ['Paranın kendisinin tüketilebilen bir mal olduğu ve değerinin yalnızca kullanımdan doğduğu', 'Paranın yalnızca altından yapılması gerektiği ve başka bir madenle olamayacağı', 'Paranın yalnızca devlete ait olduğu ve bireylerin elinde tutulamayacağı'], 'Gazali, takas düzeninin güçlüklerini anlatıp paranın yalnızca bir aracı olduğunu, biriktirilmesinin ise bu işlevi bozduğunu belirtir.'),
  ('Gazali\'nin işbölümü ve takas güçlüğünü anlatırken ortaya koyduğu fikir, modern iktisatta hangi kavramla örtüşür?', 'İhtiyaçların çifte rastlantısı sorunuyla', ['Kaynakların fırsat maliyetiyle', 'Artan marjinal verimle', 'Dış ticaret çarpanıyla'], 'Gazali, takas etmek isteyen iki tarafın ihtiyaçlarının birbirini tutmama zorluğunu anlatmıştır; modern iktisat bunu ihtiyaçların çifte rastlantısı olarak adlandırır.'),
  ('Taki\'yüddin Makrizi, 15. yüzyıl Mısır\'ındaki enflasyon ve kıtlıkları açıklarken hangi etkene özellikle dikkat çekmiştir?', 'Bakır sikkelerin (fulus) aşırı basılması ve değerli madenlerin piyasadan çekilmesi', ['Aşırı gümüş ihracı yapılması nedeniyle ülke dışına büyük miktarda para çıkması', 'Tahıl vergisinin kaldırılması ve çiftçilerin ürünlerini kendilerine saklaması', 'Haçlı seferleri nedeniyle Akdeniz ticaretinin tümüyle kesilmesi'], 'Makrizi \'İgasetü\'l-Ümme\' adlı eserinde, kötü paranın iyiyi kovması gibi bir süreci ve bunun fiyatlara etkisini yönetim hatalarıyla birlikte ele almıştır.'),
  ('İbn Teymiyye\'ye göre ortalama bir piyasa fiyatı ile haksız fiyat arasındaki ilişki nasıl açıklanabilir?', 'Fiyatlar arz ve talep dalgalanmalarıyla oluşur; zorlama ya da tekel haksızlıktır', ['Fiyatları her zaman yöneticinin tek tek belirlemesi gerekir, piyasaya güvenilemez', 'Bütün fiyatlar doğuştan sabittir ve hiçbir koşulda değişmez', 'Fiyat artışları her durumda haksızdır ve hemen cezalandırılmalıdır'], 'İbn Teymiyye, doğal arz-talep oluşumlu fiyatı meşru sayar; ancak haksız tekel veya fiyat manipülasyonuna müdahaleyi gerekli görür.'),
  ('İbn Haldun\'un işbölümü hakkında Mukaddime\'de ileri sürdüğü görüşü hangisidir?', 'Tek bir insanın ihtiyaçlarını karşılamaktan çok toplum içindeki iş paylaşımı daha fazla ürün sağlar', ['İşbölümü üretimi azaltır, çünkü insanlar tek işte uzmanlaşınca tembelleşir', 'İşbölümü yalnızca tarımda geçerlidir, sanayi ve zanaatlarda işe yaramaz', 'İşbölümü yalnızca devlet baskısıyla kurulabilir, kendiliğinden gelişmez'], 'İbn Haldun, birlikte çalışan insanların bir araya geldiğinde, yalnız başına üretebileceklerinden çok fazlasını üretebileceğini anlatır; Smith\'ten yüzyıllar önce yazılmıştır.'),
  ('İbn Haldun\'a göre devletin kendisinin büyük bir tüccar gibi davranması ekonomi üzerinde nasıl bir etki yaratır?', 'Özel girişimcilerin kârını ve ticari canlılığı azaltır', ['Fiyatları düşürür, böylece tüccarlar daha fazla mal satmaya özendirilir', 'Vergi gelirini kendiliğinden artırır ve hükümdarı zenginleştirir', 'Üretimi çoğaltır ve ülkenin ticaretini tüm yönleriyle canlandırır'], 'Mukaddime\'ye göre hükümdar ticarete girişince kaynakları ve piyasayı kendi lehine ele geçirir, tüccarların gelirini düşürür ve genel refahı bozar.'),
  ('Osmanlı siyaset yazınında sıkça işlenen \'adalet çemberi\' (daire-i adliye) düşüncesi neyi anlatır?', 'Adalet, reaya, hazine ve ordu arasında birbirini besleyen bir zincir olduğunu', ['Padişahın vergi toplamak zorunda olmadığını ve ordunun kendini finanse ettiğini', 'Esnafın tümüyle serbest bırakılması gerektiğini ve narhın kaldırılmasını', 'Dış ticaretin devlet gelirine hiç etkisi olmadığını ve yasaklanması gerektiğini'], 'Kınalızade Ali Çelebi gibi yazarlara göre devlet gücü ordudan, ordu hazineden, hazine reayanın refahından, refah ise adaletten doğar; zincir bozulursa devlet zayıflar.'),
  ('Osmanlı\'da vergi gelirlerinin belli bir süre için açık artırmayla bir kişiye devredildiği iltizam usulünün devlet için temel avantajı nedir?', 'Gelirin peşin ve önceden bilinir biçimde hazineye girmesi', ['Köylünün vergisinin tümüyle kalkması ve devlete borç ödenmemesi', 'Dış borçlanmanın gereksizleşmesi ve hazinenin dış kaynak aramaması', 'Vergi yükünün hiçbir zaman artmaması ve mültezimin sınırlandırılması'], 'Mültezim kamu gelirini önceden öder, sonra bölgeden toplayarak kâr eder; hazine nakit sıkışıklığında bu yoldan hızlı gelir sağlamıştır.'),
  ('Osmanlı kentlerindeki esnaf loncalarının ekonomik işlevlerinden biri aşağıdakilerden hangisidir?', 'Üretim kalitesini, fiyatları ve çırak-kalfa düzenini denetlemek', ['Dış ticareti yasaklamak ve yabancı tüccarların çarşıya girişini engellemek', 'Sikke basmak ve para ayarını belirlemek', 'Kırsal vergileri toplamak ve hazineye aktarmak'], 'Loncalar meslek içi standartları, hammadde dağıtımını ve rekabeti düzenler; aynı zamanda devletin narh ve vergi politikasının uygulayıcısı olurdu.'),
  ('Osmanlı\'da nakit vakıflar, sermaye birikimi ve kredi açısından hangi işlevi yerine getirmiştir?', 'Vakıf parasının belirli bir getiriyle ödünç verilerek hayır hizmetlerini finanse etmesi', ['Parasal basımı denetlemek ve sikkelerin ayarını belirlemek', 'Devletin dış borçlarını ödemek ve hazine açığını kapatmak', 'Çarşıdaki malların fiyatlarını belirlemek ve narh koymak'], 'Nakit vakıflar halka ödünç para verip yıllık getiriyle okul, çeşme gibi hizmetleri sürdürmüş; Osmanlı\'daki kredi kaynaklarının önemli bir bölümünü oluşturmuştur.'),
  ('Osmanlı\'da 16. yüzyıl sonlarında yaşanan fiyat artışlarını açıklarken hangi uluslararası gelişme öne çıkar?', 'Amerika gümüşünün Avrupa üzerinden gelip akçenin değerini düşürmesi', ['Amerika\'dan gelen şekerin vergilendirilip fiyatların düşürülmesi', 'Hindistan\'ın pamuk ihracatını yasaklayıp Osmanlı\'ya mal akışını durdurması', 'Akdeniz ticaretinin tamamen durup ithalatın azalması'], 'Gümüş bolluğu, nüfus artışı ve savaş harcamaları akçede ayar düşürmeye ve fiyat artışlarına yol açmış, 1580\'lerde köklü sorunlar yaratmıştır.'),
  ('Petty\'nin \'emek servetin babası, toprak ise anasıdır\' sözü hangi görüşü yansıtır?', 'Servetin kaynaklarının hem emek hem toprak olduğu', ['Servetin yalnızca altından geldiği', 'Emeğin değerinin ücretle belirlendiği', 'Sermayenin tek üretken etken olduğu'], 'Petty değerin ve servetin emek ve topraktan doğduğunu belirterek emek değer kuramının erken bir ifadesini vermiş, Smith ve Ricardo\'yu etkilemiştir.'),
  ('John Locke\'un 1691 tarihli faiz üzerine yazdığı risalede faiz oranının yasayla düşürülmesine yaklaşımı nedir?', 'Yasayla faizi düşürmenin etkisiz olacağını ve piyasanın faiz oranını belirleyeceğini savunmuştur', ['Faizin tamamen yasaklanmasını önermiş ve tefeciliği suç saymıştır', 'Faizin yüzde yüze çıkarılmasını önermiş ve bunu devlet eliyle yürütmüştür', 'Faizi yalnızca bankaların belirlemesini istemiş ve hükümeti dışarıda bırakmıştır'], 'Locke, faiz oranının paranın kıtlığına ve riske bağlı olarak piyasada oluştuğunu, yasal tavanın çoğu zaman aşılacağını savunmuştur.'),
  ('Thomas Mun\'un \'İngiltere\'nin Dış Ticaretle Hazinesi\' adlı eserinde para ihracatı hakkında ne savunulmuştur?', 'Daha çok mal satmak için para ihraç etmenin ülkeyi zenginleştirebileceğini', ['Altın ihracının mutlaka yasaklanması gerektiğini ve hiç ihracat yapılmamasını', 'Dış ticaretin ulusa zararlı olduğunu ve sınırların kapatılmasını', 'Gümüşün yurt içinde saklanması gerektiğini ve ticarette kullanılmamasını'], 'Mun, dış ticarette toplam bakiyenin önemli olduğunu, altın çıkarılsa bile ticaret fazlası getiren yatırımın uzun dönemde hazineyi büyüteceğini savunmuştur.'),
  ('Richard Cantillon\'a göre girişimcinin (entrepreneur) ekonomideki temel işlevi nedir?', 'Belirsiz bir gelecekte kesin maliyetle alıp belirsiz fiyatla satarak riski üstlenmek', ['Devletin harcamalarını yönetip bütçeyi dengelemek ve vergi toplamak', 'Vergi toplamak ve hazineye gelir sağlamak için devlete hizmet etmek', 'Para basmak ve dolaşımdaki para miktarını belirleyip faizi saptamak'], 'Cantillon girişimciyi risk taşıyan, kesin fiyatla girdi alıp bilinmeyen fiyatla satan aracı olarak tanımlamış ve girişimci kavramının öncüsü olmuştur.'),
  ('Pierre de Boisguilbert\'in 17. yüzyıl sonunda Fransa\'daki ekonomik sıkıntıyı Colbert uygulamalarına bağlayan eleştirisi hangi yaklaşımı öncelemiştir?', 'Piyasaya daha az müdahaleyi savunan serbestlik anlayışını', ['Altın stokunu artırmayı ve dış ticaret fazlası vermeyi öngören merkantilist anlayışı', 'Gümrük duvarlarını yükseltmeyi ve ithalatı kısıtlamayı öngören korumacılığı', 'Para basımını durdurmayı ve dolaşımdaki parayı azaltmayı öngören anlayışı'], 'Boisguilbert tahıl ticaretindeki kısıtlamaların ve ağır vergilerin tüketimi düşürüp tarımı çökerttiğini savunmuş; fizyokratların ve laissez-faire düşüncesinin öncüsü sayılır.'),
  ('Dudley North\'un 1691\'de yayımlanan \'Ticaret Üzerine Konuşmalar\' eserinde savunduğu görüş hangisidir?', 'Serbest ticaretin ve paranın serbest dolaşımının ulusal refahı artırdığını', ['Ticaret fazlasının kutsal sayılması ve her koşulda korunması gerektiğini', 'İthalatın tümüyle yasaklanması gerektiğini ve dışa kapanmanın yararını', 'Faizin devlet tarafından belirlenmesi gerektiğini ve piyasaya bırakılmamasını'], 'North, merkantilist kısıtlamaları reddetmiş, ticaretin dünya ölçeğinde iki tarafa da yararlı olduğunu savunarak klasik serbest ticaret düşüncesinin habercisi olmuştur.'),
  ('Bernard Mandeville\'in 1714 tarihli \'Arıların Masalı\' alegorisi hangi paradoksal sonucu savunur?', 'Bireylerin özel kusurlarının toplum için yarar doğurabileceğini', ['Toplumsal refahın yalnızca ahlaki erdemlerle sağlanabileceğini', 'Lüks tüketimin ulusların yoksullaşmasına yol açtığını', 'Hükümet müdahalesinin ticaret hacmini kendiliğinden artırdığını'], 'Mandeville\'e göre kibir, açgözlülük ve lüks tutkusu üretim ve istihdamı canlandırır; \'özel kusurlar, kamusal yararlar\' sözü Smith öncesi tartışmaların odağı olmuştur.'),
  ('David Hume\'a göre para arzının artması, kısa dönemde ekonomiyi nasıl etkiler?', 'Fiyatlar tam uyum sağlamadan önce üretimi ve istihdamı bir süre canlandırır', ['Fiyatlar hemen aynı oranda yükselir ve üretim hiç değişmez', 'Para arzı artınca üretim kalıcı biçimde azalır', 'Para arzı yalnızca faiz oranlarını belirleyip fiyatlara dokunmaz'], 'Hume, yeni paranın harcamaya yansıma sürecinde ilk önce üretim ve istihdamın arttığını, uzun dönemde ise sadece fiyatların yükseldiğini belirtmiştir.'),
  ('David Hume \'Faiz Üzerine\' denemesinde düşük faiz oranlarının nedenini nasıl açıklamıştır?', 'Sermaye bolluğu ve düşük kâr oranlarıyla', ['Yalnızca para arzının bolluğuyla', 'Devletin faiz tavanı koymasıyla', 'Dış ticaret fazlasının artmasıyla'], 'Hume, faiz oranının paranın miktarından çok sermaye birikimi ve kâr oranlarına bağlı olduğunu savunarak merkantilist açıklamayı reddetmiştir.'),
  ('Abbé de Condillac\'ın 1776 tarihli \'Ticaret ve Hükümet\' adlı kitabının iktisat düşüncesi için önemi nedir?', 'Değerin malın yararlılığı ve kıtlığından doğduğunu, ticaretin iki tarafa da kazanç sağladığını savunması', ['Değerin yalnızca emeğe bağlı olduğunu kanıtlayarak fayda anlayışını reddetmesi', 'Toprağı tek üretken etken ilan ederek tarım dışını verimsiz saymaları', 'Dış ticaretin sıfır toplamlı olduğunu savunarak merkantilizmi desteklemesi'], 'Condillac öznel değer anlayışının öncülerindendir; değişimin her iki tarafı da daha iyi duruma getirdiğini belirtmiştir.'),
  ('Adam Ferguson\'ın 1767 tarihli \'Sivil Toplum Tarihi Üzerine Deneme\' kitabında işbölümü hakkındaki uyarısı nedir?', 'Aşırı uzmanlaşmanın işçilerin zihnini köreltebileceği', ['İşbölümünün üretimi her koşulda azalttığı', 'Uzmanlaşmanın yalnızca tarımda zararlı olduğu', 'İşbölümünün para kullanımını gereksiz kıldığı'], 'Ferguson, tek işte uzmanlaşan işçilerin genel yeteneklerinin zayıflayacağını belirtmiş; benzer bir kaygıyı Smith de sonradan dile getirmiştir.'),
  ('Anne Robert Jacques Turgot, tarımsal üretimde yatırım arttıkça hangi olguyu gözlemlemiştir?', 'Her yeni sermaye ekiminin getirisinin giderek azaldığını', ['Her yeni yatırımın getirisinin sürekli arttığını', 'Getirinin yatırım miktarından bağımsız kaldığını', 'Toprağın yatırım yapılınca sonsuza dek verimli olduğunu'], 'Turgot\'nun 1767\'de gözlediği azalan verim eğilimi sonradan Ricardo ve Malthus tarafından toprak rant kuramında kullanılmıştır.'),
  ('Adam Smith\'in 1759 tarihli \'Ahlaki Duygular Kuramı\' adlı kitabında insan davranışını açıklamak için kullandığı temel kavram hangisidir?', 'Başkalarının duygularını paylaşan sempati ve tarafsız seyirci', ['Yalnızca bireysel fayda maksimizasyonu ve rekabet', 'Altın stoku ve ödemeler dengesi', 'Marjinal verimlilik ve rant'], 'Smith ahlaki yargının, kişinin kendisini tarafsız bir seyircinin gözüyle görmesinden doğduğunu anlatır; bu yüzden onu yalnızca bencilliğin savunucusu saymak eksiktir.'),
  ('Smith\'e göre bir malın \'doğal fiyatı\' ile \'piyasa fiyatı\' arasındaki ilişki nasıl işler?', 'Piyasa fiyatı sapmalarına karşın doğal fiyata doğru eğilim gösterir', ['Doğal fiyat piyasa fiyatından her zaman yüksektir', 'İki fiyat hiçbir zaman birbirine yaklaşmaz', 'Doğal fiyat devlet kararıyla her yıl belirlenir'], 'Doğal fiyat ücret, kâr ve rantın olağan oranlarını karşılayan fiyattır; arz-talep sapmaları geçicidir ve piyasa fiyatını bu merkeze çeker.'),
  ('Smith \'üretken emek\' ile \'üretken olmayan emek\' ayrımında, hangi emeği üretken saymıştır?', 'Satılabilir bir mala dönüşen ve değer ekleyen emeği', ['Hizmetlilerin evde gördüğü hizmet emeğini ve kişisel hizmetleri', 'Hükümet memurlarının kamu görevi çerçevesindeki çalışmasını', 'Müzisyen ve aktörlerin sahnede gösterdiği anlık emeği'], 'Smith, üretken emeğin satılabilir ve kalıcı bir mala değer eklediğini, hizmet türü emeğin ise anında yok olduğunu ve bu nedenle üretken sayılmadığını belirtmiştir.'),
  ('Smith\'in toplama (adding-up) fiyat anlayışına göre toprak sahipliği ve sermaye birikimi başladıktan sonra bir malın fiyatı hangi öğelerden oluşur?', 'Ücret, kâr ve rantın toplamından', ['Yalnızca ücretten', 'Yalnızca kâr ve vergiden', 'Altın ve gümüş miktarından'], 'Smith ilkel toplumda emeğin değer ölçüsü olduğunu, gelişmiş toplumda ise fiyatın üç gelir türünün toplamı olduğunu ileri sürmüştür.'),
  ('Smith\'e göre bazı mesleklerde ücretlerin diğerlerinden daha yüksek olmasının nedenlerinden biri hangisidir?', 'İşin zahmetli, tehlikeli ya da uzun eğitim gerektiren olması', ['İşin yalnızca toprakla ilgili olması ve tarım dışı alanlarda yürütülmesi', 'Çalışanların genellikle yaşlı olması ve emeklilik yaşına yaklaşması', 'İşçilerin yabancı uyruklu olması ve yerli halktan ayrı çalışması'], 'Smith ücret farklarını telafi edici farklılıklarla açıklar: hoş olmayan, riskli, belirsiz ya da pahalı eğitim gerektiren işler daha yüksek ücret ister.'),
  ('Smith\'in Seyir (Navigation) Yasaları\'na ilişkin görüşü, onun serbest ticaret savunusu için nasıl bir istisna oluşturur?', 'Savunma güvenliğini zenginlikten daha önemli sayarak yasaları desteklemiştir', ['Yasaları serbest ticaretin en kusursuz örneği sayıp tümüyle onaylamıştır', 'Yasaların hiçbir ekonomik etkisi olmadığını belirtip önemsememiştir', 'Yasaları köleliğin kaldırılması için eleştirip yürürlükten kaldırılmasını önermiştir'], 'Smith \'savunma zenginlikten çok daha önemlidir\' diyerek İngiliz deniz gücünü koruyan seyir yasalarını ekonomik zararlarına rağmen haklı görmüştür.'),
  ('Smith, \'Ulusların Zenginliği\' Kitap IV\'te dönemin iktisat anlayışlarını hangi iki sisteme ayırarak eleştirir?', 'Ticaret (merkantil) sistemi ve tarım sistemi', ['Para sistemi ve takas sistemi', 'Sosyalist ve kapitalist sistem', 'Altın standardı ve gümüş standardı'], 'Smith ticaret sistemini, yani merkantilizmi, ve fizyokratların tarım sistemini eleştirir; ikisinin de ekonomiye gereğinden fazla müdahale önerdiğini söyler.'),
  ('Malthus\'un 1798 tarihli \'Nüfus İlkesi Üzerine Deneme\'sinin yazılış nedeni olarak aşağıdaki hangi düşünürlerin iyimser görüşlerine yanıt vermek gösterilir?', 'Godwin ve Condorcet', ['Smith ve Hume', 'Bentham ve Mill', 'Rousseau ve Voltaire'], 'Malthus, insan toplumunun sınırsız mükemmelleşebileceğini savunan Godwin ve Condorcet\'ye karşı nüfus artışının yoksulluğu kaçınılmaz kıldığını ileri sürmüştür.'),
  ('Malthus\'un nüfusu kontrol eden \'pozitif engeller\' (positive checks) kavramı neyi içerir?', 'Kıtlık, salgın ve savaş gibi ölüm oranını artıran etkenleri', ['Geç evlilik ve evlilikten kaçınma gibi doğumları azaltan önleyici davranışları', 'Doğum kontrol yöntemlerinin yaygınlaşması ve aile planlaması', 'Devlet yardımlarının artırılması ve yoksulların desteklenmesi'], 'Malthus\'a göre nüfusu besin düzeyine indiren iki tür engel vardır: ölümleri artıran pozitif engeller ve doğumları azaltan önleyici engeller.'),
  ('Malthus, İngiltere\'deki Yoksul Yasaları\'nı neden eleştirmiştir?', 'Yardımın evlenme ve çocuk sayısını artırıp nüfus baskısını güçlendireceğini düşündüğü için', ['Yardımın yoksulları çalışmaktan caydırdığı gerekçesiyle değil, sömürüyü artırdığı için', 'Yardımın yalnızca bankaları zenginleştirdiği için', 'Yardımın dış ticareti engellediği için'], 'Malthus\'a göre yardım yoksulların çocuk yapma isteğini artırır, besin üretimini aşan nüfus yeniden yoksulluğa yol açar; bu yaklaşım Yoksul Yasası reformlarını etkilemiştir.'),
  ('Malthus\'un Ricardo\'yla yazışmalarındaki tartışma konusu olan \'genel doygunluk\' (general glut) sorunu neyi içerir?', 'Toplam talebin yetersizliğinin tüm piyasalarda aşırı arza yol açabileceği görüşünü', ['Tüm piyasalarda arzın hep talebi aştığını savunan Say yasasının sonucunu', 'Nüfusun besinden daha hızlı artarak yoksulluk yaratacağı görüşünü', 'Sermayenin yetersizliği nedeniyle üretimin durup kıtlığa yol açacağı görüşünü'], 'Malthus yetersiz talep nedeniyle genel aşırı üretim olabileceğini savunurken Ricardo Say yasasını benimsemiş; bu tartışma Keynes\'in etkin talep fikrinin öncülüdür.'),
  ('Malthus 1805\'te hangi kurumda, İngiltere\'nin ilk siyasal iktisat profesörlerinden biri olmuştur?', 'East India College', ['Oxford Üniversitesi', 'Cambridge Üniversitesi', 'Londra Ticaret Okulu'], 'Malthus Haileybury\'deki East India College\'da siyasal iktisat ve modern tarih profesörü olarak görev yapmış, İngiltere\'nin ilk iktisat profesörlerinden biri sayılmıştır.'),
  ('Ester Boserup\'un 1965 tarihli çalışması, Malthus\'un nüfus-besin anlayışına nasıl bir karşı görüş getirmiştir?', 'Nüfus baskısının tarımda yeniliği ve yoğunlaşmayı tetiklediğini savunmuştur', ['Nüfus arttıkça kıtlığın kaçınılmaz olduğunu ve üretimin gerilediğini kanıtlamıştır', 'Nüfus artışının hep üretimi azalttığını ve tarımı yok ettiğini göstermiştir', 'Besin üretiminin hiç artmadığını ve doğum oranlarının sabit kaldığını belirtmiştir'], 'Boserup\'a göre nüfus artışı tarımsal teknolojiyi geliştirmeye zorlar; bu görüş Malthusçu kıtlık kaçınılmazlığına karşı yaygın bir yanıttır.'),
  ('Malthusçu tuzak (Malthusian trap) kavramı, tarım toplumlarında hangi uzun dönem durumu anlatır?', 'Gelir artışının nüfusu artırıp kişi başına geliri tekrar yaşam düzeyine çekmesini', ['Gelirin sürekli ve hızla artıp kişi başı gelirin kalıcı olarak yükselmesini', 'Nüfusun azalıp kişi başı gelirin sürekli artmasını', 'Dış ticaretin ülkeyi sonsuza dek zenginleştirip kıtlığı ortadan kaldırmasını'], 'Teknolojik ilerleme geçici olarak kişi başı geliri artırsa da nüfus artışı bu kazancı eritir; sanayi devrimine kadar insanlığın çoğu dönemini açıklayan bir model sayılır.'),
  ('Say yasasına göre ekonomide \'genel aşırı üretim\' mümkün müdür?', 'Hayır, ancak sektörler arası dengesizlik olabilir', ['Evet, çünkü toplam talep her zaman toplam arzdan düşük kalır', 'Evet, çünkü para miktarı arttığında genel aşırı üretim kaçınılmaz olur', 'Evet, çünkü tasarruflar hiçbir zaman harcamaya dönüşmez'], 'Say yasasına göre her üretim gelir yaratır ve o gelir başka mallara harcanır; bu yüzden aşırı üretim ancak sektörler arası dengesizlik biçiminde görülür.'),
  ('Say, girişimci (entrepreneur) kavramına iktisatta hangi işlevi yüklemiştir?', 'Üretim etkenlerini birleştirip koordine etmeyi', ['Devlet adına vergi toplayıp hazineye aktarmayı', 'Yalnızca sermaye sahibi olup gelir elde etmeyi', 'Ücretli çalışan olarak tek bir işte uzmanlaşmayı'], 'Say, Cantillon\'dan sonra girişimciyi toprak, emek ve sermayeyi birleştirip üretimi yöneten ve riski üstlenen kişi olarak vurgulamıştır.'),
  ('Klasik iktisatçılar tasarrufların toplam harcamayı azaltmayacağını nasıl savunmuştur?', 'Faiz oranının tasarrufu yatırıma yönlendireceğini söyleyerek', ['Hükümetin tasarrufları bütçeden harcayacağını belirterek', 'Para arzının merkez bankasınca her zaman daraltılacağını belirterek', 'Tasarrufların kullanılmayıp saklanması durumunda fiyatların düşeceğini belirterek'], 'Klasik görüşte faiz, tasarruf arzı ile yatırım talebini eşitleyen fiyattır; bu yüzden tasarruf edilen para yatırım olarak talebe dönüşür ve toplam harcama azalmaz.'),
  ('Say\'ın Napolyon yönetimiyle ilişkisinde iktisat tarihi açısından hangi olay öne çıkar?', 'Kitabının yeni baskısına izin verilmemesi', ['Fransız maliye bakanlığına atanıp bütçeyi hazırlaması', 'Bankalar kanununu kaleme alarak Fransa Bankası\'nı kurması', 'Gümrük yasasını hazırlayarak kıta ablukasını başlatması'], 'Say, Napolyon\'un ekonomi politikasını eleştirdiği için 1804\'te meclis görevinden alınmış ve Traité\'nin yeni baskısı yasaklanmıştır; bu olay serbest düşünce ile siyaset ilişkisine örnek gösterilir.'),
  ('Keynes, \'Genel Teori\'nin ikinci bölümünde \'klasik iktisadın postülatları\' dediği şeyle esas olarak hangi iki fikri hedef almıştır?', 'Ücret-verimlilik eşitliğini ve Say yasasını', ['Paranın kıt bir mal olduğunu ve faizin devletçe belirlendiğini', 'Servetin topraktan geldiğini ve işbölümünün zararlı olduğunu', 'Dış ticaretin sıfır toplamlı olduğunu ve vergilerin yararsız olduğunu'], 'Keynes klasik görüşün iki temelini ücret-verimlilik ilişkisi ve Say yasası olarak görüp, bunların işsizliğin kalıcı olabilmesini açıklayamadığını söylemiştir.'),
  ('Walras yasası (Walras\' Law) için aşağıdakilerden hangisi doğrudur?', 'Bütün piyasaların fazla talepleri toplamı sıfırdır', ['Mal talebi her koşulda mal arzından büyüktür', 'Paranın değeri sabit tutulduğunda fiyatlar esnek kalır', 'Ücretlerin esnek olmaması işsizliği zorunlu kılar'], 'Walras yasası bütçe kısıtından türer: bir piyasa dışındakilerin hepsi dengedeyse son piyasa da dengededir; Say yasası ise toplam mal arzının toplam mal talebine eşit olduğunu ileri sürer.'),
  ('Ricardo\'ya göre emeğin \'doğal fiyatı\' (doğal ücret) neye eşittir?', 'İşçi ailesinin geçim düzeyine', ['İşverenin elde ettiği ortalama kâr miktarına', 'Toprak sahibinin aldığı rant düzeyine', 'Devletin belirlediği yasal asgari ücrete'], 'Ricardo\'ya göre uzun dönemde ücret, nüfus tepkisi nedeniyle işçinin geçim maliyetine yönelir; piyasa ücreti geçici olarak bu düzeyden sapabilir.'),
  ('Ricardo\'ya göre ekonomi büyüdükçe kâr oranına ne olur?', 'Ücret ve rant artarken kâr oranı düşer', ['Rant azaldığı için kâr oranı sürekli yükselir', 'Ücretler sabit kaldığı için kâr oranı değişmez', 'Kâr oranı yalnızca para arzındaki dalgalanmayla oynar'], 'Besin fiyatı yükselince ücretler artar ve kâr azalır; sonunda sermaye birikimi durur ve ekonomi durağan duruma yaklaşır.'),
  ('Ricardo, \'İlkeler\'in üçüncü baskısında (1821) hangi konudaki görüşünü değiştirmiştir?', 'Makinelerin işçilere zarar verebileceğini kabul etmiştir', ['Karşılaştırmalı üstünlüğün geçersiz olduğunu savunmuştur', 'Toprak rantının hiç var olmadığını ileri sürmüştür', 'Altın standardının gereksiz olduğunu belirtmiştir'], 'Ricardo daha önce makinelerin işçilere zarar vermeyeceğini düşünürken, \'makineler üzerine\' bölümünde sermayenin makineye kayması durumunda emeğe talebin düşebileceğini kabul etmiştir.'),
  ('Ricardo\'nun 1810\'da yazdığı \'Külçe Fiyatının Yüksekliği\' (High Price of Bullion) risalesindeki savı nedir?', 'Banknotun aşırı basımı külçe fiyatını yükseltmiştir', ['Altın fiyatı yalnızca savaş nedeniyle artmıştır', 'Bankaların para basmaması fiyatları yükseltmiştir', 'Altın stokları azaldığında fiyatlar düşer'], 'Ricardo, İngiltere Bankası\'nın altına çevirme yükümlülüğü kalkınca banknotları aşırı bastığını ve bunun altın fiyatını yükselttiğini savunmuştur; Bullionist tartışmanın ana metnidir.'),
  ('Ricardo, tahıl yasalarının kaldırılmasını neden savunmuştur?', 'Ucuz tahılın ücreti ve rantı düşürüp kârı artıracağını düşündüğü için', ['Tahıl ithalatının toprak sahiplerinin gelirini artıracağını düşündüğü için', 'Tahıl ihracatının altın girişini hızlandıracağını düşündüğü için', 'Tahıl yasalarının devletin vergi gelirini azalttığını düşündüğü için'], 'Korumacı tahıl yasaları iç fiyatı ve ücretleri yükseltiyor, kâr oranını düşürüyordu; Ricardo\'ya göre serbest ticaret sermayedarların ve birikimin lehineydi.'),
  ('Ricardo\'ya göre iktisat biliminin asıl sorunu nedir?', 'Ürünün sınıflar arasındaki paylaşımı', ['Paranın değerinin nasıl korunacağı sorunu', 'Dış ticaretin altın girişini nasıl artıracağı sorunu', 'Nüfusun besin kaynaklarına göre nasıl artırılacağı sorunu'], 'Ricardo, \'İlkeler\'in önsözünde dağılım yasalarını bulmanın siyasal iktisadın asıl görevi olduğunu belirtmiştir; üç sınıf toplum modeli bu yaklaşımın temelidir.'),
  ('Schumpeter\'in \'Ricardocu sapma\' (Ricardian vice) dediği yöntem eleştirisi neyi anlatır?', 'Soyut modelin sonucunu doğrudan politikaya uygulamayı', ['Verileri hiç kullanmadan yalnızca anlatı yazmayı sürdürmeyi', 'Her sonucu tarihsel örneklere dayandırıp genellemeyi', 'Her argümanı matematik diliyle ve grafiklerle ifade etmeyi'], 'Schumpeter, Ricardo\'nun basitleştirilmiş varsayımlarla elde ettiği sonuçları gerçek dünya politikalarına doğrudan taşımasını eleştirmiş; terim bugün de yöntem tartışmalarında kullanılır.'),
  ('Ricardo\'nun değer kuramında \'değişmez değer ölçüsü\' sorunu neden ortaya çıkar?', 'Ücret değişince göreli fiyatlar da değişir', ['Altının değeri her dönemde aynı kaldığı için', 'Emek saatinin uzunluğu her işte eşit olduğu için', 'Toprak miktarının sınırsız olduğu varsayıldığı için'], 'Ücret artışı sermaye-yoğun ve emek-yoğun malların göreli fiyatını farklı etkilediği için, yalnızca emek miktarı değeri tam açıklayamaz; Ricardo bu yüzden değişmez ölçü arar.'),
  ('Ricardo\'nun 1815 tarihli \'Düşük Mısır Fiyatının Sermaye Kârlarına Etkisi\' yapıtı hangi konuya yöneliktir?', 'Tahıl fiyatı, ücret ve kâr ilişkisine', ['Banka kredilerinin faiz oranına etkisine', 'Dış borçların hangi yolla ödenebileceğine', 'Gümüş sikkelerin ayarının nasıl korunacağına'], 'Ricardo bu denemede tahıl fiyatı, ücretler, rant ve kâr ilişkisini ilk kez sistemli biçimde ortaya koymuş; sonraki \'İlkeler\'in öncüsü olmuştur.'),
  ('Ricardo\'nun görüşünde toprak sahipleri sınıfının büyümedeki rolü nasıl yorumlanır?', 'Rant artarken üretime katkısı sınırlı bir sınıf', ['Üretimin asıl yönlendiricisi olan dinamik bir sınıf', 'Kâr oranını koruyan ve sermaye yaratan bir sınıf', 'İşçi ücretlerini yükselten ve istihdam sağlayan bir sınıf'], 'Ricardo, büyüme ilerledikçe rantın payının arttığını ve toprak sahiplerinin gelirlerini üretken katkıda bulunmadan artırdıklarını düşünüyordu; bu nedenle tahıl korumacılığına karşıydı.'),
  ('Bentham\'ın 1787 tarihli \'Tefeciliğin Savunusu\' (Defence of Usury) adlı yapıtı kime ve neye karşı yazılmıştır?', 'Faiz tavanını savunan Adam Smith\'e karşı', ['Altın standardını savunan Ricardo\'ya karşı', 'Tahıl yasalarını savunan Malthus\'a karşı', 'Kâğıt parayı savunan Hume\'a karşı'], 'Bentham, yasal faiz tavanlarının yararlı girişimleri engellediğini ve sözleşme özgürlüğünün korunması gerektiğini savunarak Smith\'i bile eleştirmiştir.'),
  ('Mill\'in \'Siyasal İktisadın İlkeleri\'nde üretim ve dağılım arasında yaptığı ayrım nedir?', 'Üretim doğa yasalarına bağlı, dağılım toplumsal kurumlara bağlıdır', ['Üretim devletin işi, dağılım ise yalnızca piyasanın işleyişine bağlı bir konudur', 'Üretimin kuralları coğrafyaya, dağılımın kuralları dinî inançlara göre belirlenir', 'Üretim yalnızca kısa dönemli, dağılım ise yalnızca uzun dönemli bir konudur'], 'Mill\'e göre üretimin yasaları fiziksel gerçekliğe dayanırken, ürünün nasıl paylaşılacağı insan kararlarına, yasalara ve geleneklere bağlıdır.'),
  ('Mill\'in \'durağan hâl\' (stationary state) için tutumu Ricardo\'dan nasıl ayrılır?', 'Onu karamsar değil, insani gelişim için olumlu bir hâl olarak görmüştür', ['Onu ekonomik ve toplumsal bir felaket olarak görüp her koşulda engellenmesi gereken bir durum saymıştır', 'Onu yalnızca reel ücretlerin hızla yükseleceği geçici bir dönem olarak değerlendirmiştir', 'Onu iktisat kuramı açısından tümüyle imkânsız ve anlamsız bir durum saymıştır'], 'Mill, büyümenin durduğu ekonomide sermaye ve nüfusun sabit kalmasını, insanların kültürel ve ahlaki gelişime yönelebileceği bir hâl olarak memnuniyetle karşılamıştır.'),
  ('Mill\'in \'Siyasal İktisadın Tanımı Üzerine\' (1836) denemesi hangi kavramın yerleşmesine katkı yapmıştır?', 'Yalnızca servet peşinde koşan soyut \'iktisadi insan\' modelinin', ['Altın ve gümüş stokunu ulusal servetin tek ölçüsü sayan külçecilik anlayışının', 'Bireylerin ahlaki duygularını paylaşan sempatik seyirci kavramının', 'Gelir düzeyinden bağımsız çalışan toplam harcama ilkesinin'], 'Mill, iktisat biliminin insanı yalnızca zenginlik edinmeyi isteyen biri olarak soyutladığını belirtmiş; böylece \'homo economicus\' yöntemsel bir varsayım olarak kabul edilmiştir.'),
  ('Mill, serbest ticaret ilkesine rağmen \'yeni sanayi\' konusunda hangi istisnayı kabul etmiştir?', 'Yeni kurulan sanayinin geçici korunmasını', ['Tarım ürünlerine kalıcı ihracat yasağı koymayı', 'Ham madde ithalatına sınırsız vergi koymayı', 'Yabancı yatırımcıları yasaklamayı'], 'Mill, kendi başına ayakta duramayacak genç sanayiler için geçici ve sınırlı koruma sağlanabileceğini kabul eden ilk büyük klasik iktisatçılardandır.'),
  ('Mill\'in \'Özgürlük Üzerine\' eserindeki \'zarar ilkesi\'nin (harm principle) iktisat politikasına yansıması nasıl olur?', 'Devlet yalnızca başkalarına zarar veren eylemleri sınırlamalıdır', ['Devlet her türlü ekonomik kararı denetleyip düzenleyen kapsamlı bir plan hazırlamalıdır', 'Devlet yalnızca kendi kendine zarar veren bireyleri cezalandırmakla yetinmelidir', 'Devlet hiçbir koşulda fiyatlara ya da sözleşmelere müdahale etmemelidir'], 'Zarar ilkesi bireyin özgürlüğünün ancak başkalarına zarar verdiğinde sınırlanabileceğini söyler; Mill bu fikri hem kişisel hem ekonomik özgürlükler için kullanmıştır.'),
  ('Nassau Senior\'ın \'perhiz kuramı\' (abstinence theory) kârı nasıl açıklar?', 'Kâr, tüketimden kaçınıp tasarruf etmenin ödülüdür', ['Kâr, emeğin ürününden işçiye ödenmeyen kısımdan doğan artıdır ve sömürüye dayanır', 'Kâr, toprak sahibinin üretimden aldığı rantın bir türüdür ve doğal fiyatı belirler', 'Kâr, para arzının artması sonucunda ortaya çıkan fiyat yükselmesinden kaynaklanır'], 'Senior\'a göre sermayedar harcamayı ertelemekle fedakârlık eder; kâr bu fedakârlığın karşılığıdır. Marx bu kurama karşı çıkmıştır.'),
  ('Frédéric Bastiat\'nın \'Mumcuların Dilekçesi\' hicvi hangi savı alaya alır?', 'Yerli üreticiyi korumak için ucuz yabancı rekabete engel konulması gerektiği', ['Güneş ışığının üretimi artırmak amacıyla devlet tarafından yeniden kullanılmasının gerektiği', 'Devletin üreticileri korumak için ücretleri yasa ile yükseltmesinin gerektiği', 'Sermayenin tüm sektörlerden çekilip yalnızca tarım sektörüne yönelmesinin gerektiği'], 'Bastiat, mum üreticilerinin \'güneşin haksız rekabetine\' karşı yasa istediğini anlatarak gümrük korumacılığının mantıksızlığını göstermiştir.'),
  ('Johann Heinrich von Thünen\'in \'Yalıtılmış Devlet\' (1826) modelinde tarımsal üretimin yerleşimini hangi etken belirler?', 'Pazara olan uzaklık ve taşıma maliyeti', ['Hükümdarın sarayına ya da başkente olan siyasal ve idari yakınlık derecesi', 'Toprağın kimyasal bileşimi ve yağış miktarının yıllara göre değişimi', 'Bölge nüfusunun inanç yapısı ve geleneksel tarım takvimi'], 'Thünen, kenti merkez alan bir ovada üretim türlerinin taşıma maliyeti ve rant farkıyla konsantrik halkalar halinde dizildiğini göstermiştir.'),
  ('Jules Dupuit\'nin 1844 tarihli köprü ve yol yapımı üzerine yazdığı makalede ortaya koyduğu fikir hangisidir?', 'Kullanıcıların ödemeye razı olduğu miktar ile ödediği fiyat arasındaki farkın bir yarar olduğu', ['Kamu yatırımlarının tümüyle özel sektöre bırakılması gerektiği', 'Vergilerin yalnızca ithalattan alınması gerektiği', 'Kamu harcamalarının her zaman enflasyona yol açtığı'], 'Dupuit, bir kamu mal veya hizmetinden doğan tüketici artığının ölçülebileceğini göstermiş; bu fikir Marshall\'ın tüketici rantına zemin hazırlamıştır.'),
  ('Robert Torrens\'in 1815 tarihli yazılarında Ricardo\'dan önce işaret ettiği fikir hangisidir?', 'Karşılaştırmalı üstünlük ilkesinin ilk izleri', ['Marjinal verimlilik kuramının tam ve sistemli hâlinin ilk anlatımını', 'Emek fonuna dayanan ücret kuramının ilk açık anlatımını', 'Etkin talep ilkesinin ve çarpan etkisinin ilk açık anlatımını'], 'Torrens, 1815\'te İngiltere ve Polonya arasındaki ticaretin bir ülkenin mutlak üstünlüğü olmasa bile kazanç sağlayacağını belirtmiş; ilke genelde Ricardo ile anılır.'),
  ('Saint-Simon\'un toplumu \'sanayiciler\' ve \'asalaklar\' olarak ayırmasında asalak sınıfa kimler girer?', 'Çalışmayan soylular, rahipler ve rantiyeler', ['Çiftçiler, zanaatkârlar ve atölye sahipleri gibi ürün üreten halk kesimleri', 'Bankacılar, tüccarlar ve fabrika sahipleri gibi üretimi finanse eden kesimler', 'Mühendisler, bilim insanları ve sanatçılar gibi toplumu ileri taşıyan kesimler'], 'Saint-Simon, üretimde yer alan herkesi \'sanayici\' sayıp, üretmeden yaşayan soylu ve din adamlarını eleştirmiş; sanayi toplumunun yönetilmesi gerektiğini savunmuştur.'),
  ('Marx\'ın 1847\'de Proudhon\'un \'Sefaletin Felsefesi\' adlı kitabına yanıt olarak yazdığı kitap hangisidir?', 'Felsefenin Sefaleti', ['Alman İdeolojisi', 'Ekonomi Politiğin Eleştirisine Katkı', 'Louis Bonaparte\'ın 18 Brumaire\'i'], 'Marx, adı Proudhon\'un kitabının tersine çevrilmiş bir yanıt olarak \'Felsefenin Sefaleti\'ni yazmış ve Proudhoncu iktisadı eleştirmiştir.'),
  ('Louis Blanc\'ın 1839 tarihli \'Çalışmanın Örgütlenmesi\' kitabından esinlenen 1848 Fransız uygulaması hangisidir?', 'Ulusal atölyeler (ateliers nationaux)', ['Büyük girişimlere sermaye aktaran ulusal bir merkez bankası uygulaması (Fransa Bankası)', 'Fransa ile komşu ülkeler arasında kurulan bir gümrük birliği uygulaması', 'Tahıl ticaretinin tek elde toplandığı devlet tekeli uygulaması'], '1848 devriminden sonra işsizlere iş sağlamak için kurulan ulusal atölyeler Blanc\'ın fikirlerinden esinlenmiştir; Haziran\'da kapatılınca ayaklanma çıkmıştır.'),
  ('Friedrich Engels\'in \'Ütopik ve Bilimsel Sosyalizm\' kitabında Saint-Simon, Fourier ve Owen için yaptığı değerlendirme nedir?', 'Haklı eleştiriler getirmişler, ancak tarihsel maddeci çözümlemeden yoksun kalmışlardır', ['Marx\'tan önce bilimsel sosyalizmi tam olarak kuran ve tarihsel maddeciliği bulan düşünürlerdir', 'Kapitalizmi savunan ve piyasa düzenini öven liberal düşünürlerdir', 'Hiçbir doğru gözlem yapmamış, tümüyle yanlış fikirler üretmiş düşünürlerdir'], 'Engels onları ahlaki çağrıyla yetinen \'ütopik\' düşünürler olarak nitelemiş, kendi yaklaşımını sınıf mücadelesine dayanan \'bilimsel sosyalizm\' diye adlandırmıştır.'),
  ('Ricardocu sosyalistler olarak anılan Thomas Hodgskin ve William Thompson\'ın ortak savı nedir?', 'Emek değer kuramından yola çıkarak işçinin emeğinin tam ürününe hakkı olduğu', ['Altın standardı yoluyla ücretlerin sabit tutulması gerektiğini ve kâr payının korunmasını', 'Rantın tümüyle serbest bırakılması ve toprak mülkiyetinin sınırsız savunulmasını', 'Toprak mülkiyetinin devlete devrinin zorunlu olduğunu ve piyasanın kaldırılmasını'], 'Ricardo\'nun emek değer kuramını benimseyen bu yazarlar, kârı ve rantı emeğe verilmeyen ürün olarak yorumlamış, Marx\'ın artı değer kuramına zemin hazırlamıştır.'),
  ('Marx\'a göre bir metanın değerini belirleyen şey nedir?', 'Toplumsal olarak gerekli emek zamanı', ['Alıcının o mala duyduğu öznel gereksinim ve fayda düzeyi', 'Üretimde kullanılan altın ve gümüş madenlerinin toplam miktarı', 'Devletin koyduğu vergi ve harçlarla belirlenen resmî fiyat'], 'Ortalama teknik ve beceri koşullarında bir metanın üretimi için gereken emek süresine toplumsal olarak gerekli emek zamanı denir; değer bu süreyle ölçülür.'),
  ('Marx\'a göre kapitalistin işçiden satın aldığı şey nedir?', 'Emek gücü', ['Emeğin tam ürünü ve işçinin ürettiği tüm değer', 'İşçinin tüm yaşamı boyunca çalışma yükümlülüğü', 'Üretimde kullanılacak makine ve hammadde miktarı'], 'Marx\'a göre işçi emeğini değil emek gücünü satar; emek gücünün değeri geçim araçlarının değeriyle belirlenir, emek ise bundan daha fazla değer yaratabilir.'),
  ('Marx\'ın \'artı değer\' kavramı neyi anlatır?', 'İşçinin ürettiği değerin emek gücünün değerini aşan kısmını', ['Kapitalistin ödediği ücretle elde ettiği toplam satış hasılası arasındaki farkı', 'Toprak sahibinin kiraya verdiği topraktan aldığı rant payını', 'Bir malın fiyatı ile devletin koyduğu vergi arasındaki farkı'], 'İşçi, ücretinin karşılığı olan değeri belirli bir sürede üretir; kalan çalışma süresinde yarattığı değer ise artı değerdir ve kâr, faiz, rant biçiminde paylaşılır.'),
  ('Marx\'ın terimleriyle sabit sermaye c = 80, değişen sermaye v = 20 ve artı değer s = 20 ise artı değer oranı ve kâr oranı sırasıyla nedir?', 'Yüzde 100 ve yüzde 20', ['Yüzde 20 ve yüzde 100 olarak sırasıyla', 'Yüzde 25 ve yüzde 80 olarak sırasıyla', 'Yüzde 100 ve yüzde 25 olarak sırasıyla'], 'Artı değer oranı s/v = 20/20 = %100; kâr oranı s/(c+v) = 20/100 = %20 olur.'),
  ('Marx\'a göre \'mutlak artı değer\' nasıl artırılır?', 'Çalışma gününü uzatarak', ['Üretim teknolojisini geliştirip gerekli emek zamanını kısaltarak', 'Ücretleri düşürüp geçim araçlarının fiyatını artırarak', 'Daha çok sermaye yatırıp rant payını yükselterek'], 'Mutlak artı değer, gerekli emek süresi sabitken çalışma süresini uzatmakla; göreli artı değer ise verimliliği artırıp gerekli emek süresini kısaltmakla sağlanır.'),
  ('Marx\'ın \'sanayi yedek ordusu\' kavramı hangi gruba işaret eder?', 'Ücretleri düşük tutan işsiz ya da yarı işsiz işçi kitlesine', ['Fabrikalarda gece vardiyasında çalışan, ücreti yüksek ve sendikalı işçi kesimine', 'Askerî sanayide görev alan, devletin yetiştirdiği teknik personele', 'Yurt dışına göç ederek yüksek ücret alan nitelikli işçilere'], 'İşsizlerin varlığı çalışan işçileri ücret pazarlığında zayıflatır; kapitalizmin makineleşmesi emek talebini azalttıkça yedek ordu büyür.'),
  ('Marx\'a göre kâr oranının düşme eğiliminin ana nedeni nedir?', 'Sermayenin organik bileşiminin yükselmesi', ['Ücretlerin sürekli düşmesi ve işçi sayısının artması', 'Faiz oranlarının tüm sektörlerde birden artması', 'Toprak rantının kâr üzerinde sıfıra inmesi'], 'Makineleşmeyle sabit sermayenin değişen sermayeye oranı artar; artı değerin kaynağı yalnızca emek olduğundan, toplam sermayeye göre kâr oranı düşme eğilimi gösterir.'),
  ('Marx\'ın \'ilkel birikim\' kavramı hangi tarihsel süreci anlatır?', 'Üreticilerin topraktan koparılması gibi, kapitalizmin ön koşullarını yaratan zor kullanma süreçlerini', ['Kapitalistlerin gelirlerinden tasarruf ederek zamanla biriktirdikleri sermayeyi ve bu sürecin ahlaki yönünü', 'Altın madenlerinden çıkan servetin bankalarda toplanıp ticarete dönüştürülmesi sürecini', 'Zanaatkârların loncalar kurarak üretimlerini örgütlemesi ve ustalaşma sürecini'], 'Marx, kapitalizmin \'masum\' bir tasarruf hikâyesiyle değil, çitleme, sömürgecilik ve zorla mülksüzleştirmeyle doğduğunu savunur; Kapital\'in birinci cildinde bu konu işlenir.'),
  ('Marx\'ın \'meta fetişizmi\' kavramı neyi anlatır?', 'İnsanlar arasındaki toplumsal ilişkilerin şeyler arasındaki ilişki gibi görünmesini', ['İnsanların metalara dinî ve büyüsel anlamlar yükleyip onları kutsal saymasını ve tapınma biçimine sokmasını', 'Tüketicilerin yalnızca gösteriş amacıyla pahalı mal edinip toplumsal çevresine sergilemesini', 'Paranın bir gün tümüyle altına dönüştürülebileceği inancının yaygınlaşmasını ve spekülasyonu'], 'Marx\'a göre piyasada değer, metaların doğal bir özelliği gibi algılanır; oysa gerçekte bu, emek ilişkilerinin toplumsal sonucudur.'),
  ('Marx\'ın tarihsel maddeciliğinde \'alt yapı\' neyi ifade eder?', 'Üretim güçleri ve üretim ilişkilerinin oluşturduğu ekonomik temeli', ['Hukuk, din ve felsefe gibi toplumsal düşünce ve inanç biçimlerinin tamamını ifade eder', 'Devletin siyasal kurumlarını, ordusunu ve kamu düzenini ifade eder', 'Halkın geleneksel ahlak anlayışını ve sanat üretimini ifade eder'], 'Marx\'a göre ekonomik alt yapı hukuk, siyaset, din ve ideolojiden oluşan üst yapıyı büyük ölçüde belirler.'),
  ('Marx\'ın 1859 tarihli önsözünde sıraladığı üretim tarzları arasında aşağıdakilerden hangisi yer alır?', 'Asya üretim tarzı', ['Merkantilist üretim tarzı', 'Küreselleşmiş üretim tarzı', 'Bilgi tabanlı üretim tarzı'], 'Marx; Asya, antik, feodal ve modern burjuva üretim tarzlarını toplumsal gelişmenin ardışık dönemleri olarak anar.'),
  ('Marx\'ın yeniden üretim şemalarında (\'Kapital\' ikinci cilt) iki bölüm hangi üretimleri ifade eder?', 'Üretim araçları ve tüketim malları', ['Tarım üretimi ve hizmet üretimi olmak üzere iki sektörü', 'Yurt içi ticaret ve dış ticaret olmak üzere iki alanı', 'Kamu sektörü ve özel sektör olmak üzere iki alanı'], 'Marx, genişletilmiş yeniden üretimin sürebilmesi için üretim araçları (I. bölüm) ile tüketim mallarının (II. bölüm) belirli oranlarda büyümesi gerektiğini gösterir.'),
  ('Lenin\'in 1916 tarihli \'Emperyalizm, Kapitalizmin En Yüksek Aşaması\' eserinin temel savı hangisidir?', 'Tekeller ve finans sermayesi dünyayı bölüşür', ['Serbest rekabet dünya pazarında gittikçe güçlenir ve tekelleri yok eder', 'Emperyalizm yalnızca askerî güç gösterisinden ibaret, ekonomik temeli olmayan bir olgudur', 'Sömürgeler ana ülkelerin ekonomisi için hiçbir ekonomik önem taşımaz'], 'Lenin, kapitalizmin sermaye ihracı, tekeller ve bankacılık sermayesiyle birleşen sanayi sermayesi etrafında emperyalist aşamaya geçtiğini savunmuştur.'),
  ('Rosa Luxemburg\'un \'Sermaye Birikimi\' (1913) adlı eserinde ileri sürdüğü görüş nedir?', 'Kapitalizm yaşamak için kapitalist olmayan dış pazarlara gereksinim duyar', ['Kapitalizm kendi iç pazarında sınırsız biçimde büyüyebilir ve dışarıya muhtaç değildir', 'Sermaye birikimi yalnızca tasarruf oranının yükselmesiyle sınırlanır', 'Sömürgecilik kapitalizmin gelişmesine hiçbir katkı sağlamaz, tersine zarar verir'], 'Luxemburg, artı değerin yalnızca kapitalist ekonomi içinde gerçekleştirilemeyeceğini ve bu yüzden emperyalizmin birikim için zorunlu olduğunu ileri sürmüştür.'),
  ('Rudolf Hilferding\'in 1910\'da yayımlanan \'Finans Kapital\' kitabında hangi gelişmeye dikkat çekilir?', 'Sanayiyi bankaların denetlemesine', ['Bankaların sanayiden bağımsızlaşıp küçüldüğüne ve işlevini yitirdiğine', 'Sanayi sermayesinin bankacılığa tümüyle karşı çıktığına', 'Finans piyasalarının devletçe tamamen devralındığına'], 'Hilferding, bankaların sanayi şirketlerine kredi ve hisse yoluyla hâkim olmasını ve tekelleşme eğilimini kapitalizmin yeni evresi olarak çözümlemiştir.'),
  ('Eduard Bernstein\'ın 1899\'da \'Evrimci Sosyalizm\' (revizyonizm) görüşünde savunduğu fikir nedir?', 'Sosyalizme devrim yerine reformlarla ve parlamenter yolla ulaşılabileceği', ['Kapitalizmin kısa sürede çökeceği ve devrimin kaçınılmaz olduğu', 'Sosyalizmin yalnızca silahlı ayaklanma yoluyla kurulabileceği', 'Sendikaların kapatılıp özel mülkiyetin tümüyle devletleştirilmesi gerektiği'], 'Bernstein, Marx\'ın beklediği çöküşün gerçekleşmediğini, işçi koşullarının iyileştiğini belirterek Alman Sosyal Demokrat Partisi\'ni reformist çizgiye çağırmıştır.'),
  ('Antonio Gramsci\'nin \'hegemonya\' kavramı neyi anlatır?', 'Rıza ve kültür yoluyla yönetmesini', ['Devletin ekonomiyi tamamen kamulaştırarak yönetmesini', 'Sınıf mücadelesinin yalnızca silahlı çatışmalara dönüşmesini', 'Sermaye birikiminin merkez bankası politikalarıyla yönlendirilmesini'], 'Gramsci, burjuvazinin iktidarını yalnızca baskıyla değil, okul, basın, kilise gibi kurumlarla ürettiği rızayla da sürdürdüğünü savunmuştur.'),
  ('Paul Baran ve Paul Sweezy\'nin 1966 tarihli \'Tekelci Sermaye\' kitabında öne sürdükleri sorun hangisidir?', 'Artığın etkin soğurulamamasına', ['Tekelci kapitalizmin ücretleri sürekli yükselttiği ve kâr oranlarını düşürdüğü', 'Tekelci kapitalizmin rekabeti artırarak fiyatları sürekli düşürdüğü', 'Tekelci kapitalizmin bütün gelirleri tarıma aktardığı'], 'Baran ve Sweezy, büyük firmaların fiyat rekabetinden kaçınarak yüksek artık yarattığını ve bunun yatırım, tüketim ve askerî harcamalarla yeterince emilemediğini savunmuşlardır.'),
  ('Oskar Lange\'nin 1936-37 tarihli \'Sosyalizmin İktisat Kuramı Üzerine\' yazısında önerdiği model nedir?', 'Deneme-yanılmayla fiyat belirleyen piyasa sosyalizmi', ['Fiyatların tamamen piyasada serbestçe oluştuğu ve devletin hiç bulunmadığı bir düzen', 'Para ve fiyatların kaldırılıp yalnızca ayni dağıtımın yapıldığı bir düzen', 'Tarımın ve sanayinin tümüyle yabancı sermayeye devredildiği bir düzen'], 'Lange, Mises ve Hayek\'in sosyalist hesap eleştirisine yanıt olarak, planlama kurulunun fiyatları deneme-yanılmayla ayarlayarak rasyonel hesap yapabileceğini savunmuştur.'),
  ('Alman Tarihçi Okulu\'nun iktisat eğitimine bıraktığı kalıcı etkilerden biri hangisidir?', 'Kurumsal bağlamın çözümlemeye katılması', ['Matematiksel modellerin tümüyle bırakılması gerekliliği', 'Para arzının tek belirleyici olduğu fikri', 'Bireysel faydanın ölçülebilir olduğu görüşü'], 'Tarihçi okul, kurumsal ve tarihsel çözümlemeyi iktisata taşıyarak Amerikan kurumsalcılığını ve iktisat tarihini etkilemiştir.'),
  ('Marjinalist iktisatta tüketicinin dengeye ulaştığı koşul nasıl ifade edilir?', 'Son paraya düşen marjinal faydaların mallar arasında eşit olması', ['Toplam faydanın mallar arasında eşit dağılması koşulu', 'Her mal için ödenen fiyatın birbirine eşit olması koşulu', 'Bütün malların miktarlarının birbirine eşit olması koşulu'], 'Tüketici, her mala harcadığı son liradan elde ettiği marjinal faydayı eşitleyene dek harcamasını yeniden dağıtır; bu Gossen ve Jevons\'un da vurguladığı ilkedir.'),
  ('Eugen von Böhm-Bawerk\'in \'dolambaçlı üretim\' (roundabout production) fikri hangi sonuca varır?', 'Daha uzun üretim süreçleri daha çok mal verir ama sermaye ve zaman gerektirir', ['Daha kısa üretim süreçleri her zaman daha fazla mal verir ve sermayeyi azaltır', 'Üretim süreçlerinin uzunluğu çıktı miktarını hiçbir biçimde etkilemez', 'Daha uzun üretim süreçleri yalnızca işçi sayısını artırıp ürünü azaltır'], 'Böhm-Bawerk\'e göre üretim araçları yapmak zaman alır, ancak bu dolambaçlı yol nihai ürünü artırır; faiz de bekleme zamanının karşılığıdır.'),
  ('Mises\'in \'praxeology\' (insan eylemi bilimi) yaklaşımı iktisat yöntemi açısından neyi savunur?', 'İktisadın deneysel testlerden çok mantıksal tümdengelimle kurulması gerektiğini', ['İktisadın yalnızca ekonometrik verilere dayanması gerektiğini', 'İktisadın yalnızca tarihsel örneklerden çıkarım yapması gerektiğini', 'İktisadın gözlemlenen davranıştan bağımsız olarak ahlaki yargılara dayandırılması gerektiğini'], 'Mises, insanın amaçlı eylemde bulunduğu önermesinden mantıksal çıkarımlarla iktisat yasalarına ulaşılabileceğini; verilerin kuramı çürütemeyeceğini düşünmüştür.'),
  ('Hayek\'in \'kendiliğinden oluşan düzen\' (spontaneous order) kavramı neyi anlatır?', 'Kimsenin bilinçli tasarlamadığı ama insan eylemlerinden doğan düzeni', ['Devletin tasarlayıp zorunlu kıldığı planlı üretim düzenini', 'Tanrısal bir güç tarafından kurulduğu varsayılan toplumsal düzeni', 'Askerî komuta ile işleyen hiyerarşik ekonomik düzeni'], 'Dil, piyasa ve hukuk gibi kurumlar Hayek\'e göre birçok kişinin karşılıklı uyumuyla ortaya çıkar; bu tür düzenler tasarlanmaktan çok evrilir.'),
  ('Alfred Marshall, iktisadı \'insanlığın olağan yaşam işlerindeki incelenmesi\' diye tanımlayarak hangi yaklaşımı benimsemiştir?', 'Servet incelemesinin yanında insanın refahını da önemseyen bir yaklaşımı', ['İktisatı yalnızca para ve altın stokunun incelenmesine indirgeyen bir yaklaşımı', 'İktisatı yalnızca devletin gelir ve giderleriyle sınırlayan bir yaklaşımı', 'İktisadı yalnızca sınıf çatışmasının analizi olarak gören bir yaklaşımı'], 'Marshall iktisadın hem servet hem de insan refahı ile ilgili olduğunu vurgulamış; bu tanım iktisadı salt servet bilimi görüşünden uzaklaştırmıştır.'),
  ('Marshall\'ın piyasa dönemi, kısa dönem ve uzun dönem ayrımının amacı nedir?', 'Zamanın arz uyumunu nasıl etkilediğini göstermek', ['Devletin plan dönemlerini yıllık hedeflere bölmek', 'Bankaların vade yapısını sınıflandırmak', 'Hükümetlerin vergi dönemlerini belirlemek'], 'Marshall, fiyatın kısa dönemde talep, uzun dönemde maliyet tarafından daha çok belirlendiğini; zaman uzadıkça arzın uyum esnekliğinin arttığını göstermiştir.'),
  ('Marshall\'ın \'yarı rant\' (quasi-rent) kavramı neyi anlatır?', 'Kısa dönemde sabit araçların rant benzeri getirisini', ['Toprak sahibinin aldığı sürekli kira gelirini', 'Devlete ödenen vergi ve harçları', 'İşçilere ödenen ek mesai ücretini'], 'Kısa dönemde arzı artırılamayan makine gibi araçlar, fiyat yükselince rant gibi bir kazanç sağlar; uzun dönemde bu getiri yeni yatırımlarla aşınır.'),
  ('Marshall\'ın \'temsilî firma\' kavramı hangi amaçla kullanılır?', 'Sektörün ortalama koşullarını temsil eden firmayı tanımlamak için', ['Sektörün en büyük ve tekel gücüne sahip firmasını tanımlamak için', 'Devlet işletmelerini özel işletmelerden ayırmak için', 'Sektöre girmek isteyen yabancı firmaları işaretlemek için'], 'Temsilî firma, sektörün normal koşullarını yansıtan ortalama bir firmadır; Marshall böylece tek tek firmaların farklılıklarından soyutlayarak sektör çözümlemesi yapar.'),
  ('Marshall\'ın \'dışsal ekonomiler\' fikri hangi olguyu açıklar?', 'Aynı sektördeki firmaların kümelenmesinden doğan ortak yararları', ['Bir firmanın kendi içinde yaptığı uzmanlaşmadan doğan maliyet düşüşünü', 'Devletin sektöre doğrudan sağladığı sübvansiyonları', 'Bir sektördeki tekelin fiyat üzerindeki belirleyici gücünü'], 'Marshall endüstri bölgelerinde nitelikli işgücü, uzman tedarikçiler ve bilgi yayılımının sektörde yer alan tüm firmalara fayda sağladığını göstermiştir.'),
  ('Cambridge nakit bakiyeleri yaklaşımında \'k\' katsayısı neyi gösterir?', 'İnsanların gelirinin ne kadarını nakit olarak tuttuğunu', ['Devletin gelirinin ne kadarını vergi olarak topladığını', 'Bankaların mevduatının ne kadarını kredi olarak verdiğini', 'Paranın bir yılda ortalama kaç kez el değiştirdiğini'], 'M = kPY denkleminde k, gelirin nakit tutulan oranıdır; Fisher\'in dolaşım hızına dayalı denkleminin tersi gibidir (k = 1/V).'),
  ('Marshall\'ın uzun dönem arz eğrisinin eğimi için ileri sürdüğü, \'artan, sabit ya da azalan maliyet\' sektörlerini ayıran etken nedir?', 'Sektör büyüdükçe maliyetlerin değişimi', ['Devletin sektöre koyduğu vergi oranı', 'Sektördeki işçilerin sendikalaşma düzeyi', 'Sektörün kullandığı paranın türü'], 'Marshall, sektör genişledikçe girdi fiyatlarının artması ya da dışsal ekonomilerle maliyetlerin düşmesi gibi etkenlerin uzun dönem arz eğrisini belirlediğini göstermiştir.'),
  ('Marshall\'ın \'Ekonominin İlkeleri\'nde talep ve arz arasında \'makasın iki ağzı\' benzetmesini kullanmasının yöntemsel anlamı nedir?', 'Fiyatın iki yönlü oluştuğunu göstermesi', ['Genel denge çözümlemesinde bütün piyasaları aynı anda ele alması', 'Maliyetin tek başına fiyatı belirlediğini savunması', 'Fiyatın yalnızca devletçe belirlendiğini göstermesi'], 'Marshall, ceteris paribus varsayımıyla tek piyasayı ayrıştırıp talep ve arz güçlerinin birlikte fiyatı belirlediğini savunan kısmi denge yöntemini benimsemiştir.'),
  ('Walras\'ın \'tâtonnement\' (deneme-yanılma) süreci neyi anlatır?', 'Açık artırmayla fiyatların dengeye ayarlanmasını', ['Fiyatların devletçe yıllık olarak belirlenip ilan edilmesini', 'Fiyatların merkez bankasınca sabitlenip güncellenmesini', 'Fiyatların her işlemde pazarlıkla ayrı belirlenmesini'], 'Walras, bir açık artırmacının fazla talep varsa fiyatı yükselttiği, fazla arz varsa düşürdüğü bir süreçle genel dengeye ulaşıldığını modellemiştir.'),
  ('Pareto\'nun fayda anlayışında Jevons ve Walras\'tan farklı olarak getirdiği yenilik nedir?', 'Kardinal fayda yerine sıralamaya dayalı (ordinal) fayda yeterliydi', ['Faydanın birimlerle toplanabildiği ve karşılaştırılabildiği görüşünü savundu', 'Faydanın hiç önem taşımadığını ve yalnızca maliyetin belirleyici olduğunu savundu', 'Faydanın yalnızca devletin harcamalarıyla ilişkili olduğunu savundu'], 'Pareto, tercihlerin yalnızca sıralanabilmesinin yeterli olduğunu göstererek kayıtsızlık eğrisi yaklaşımının ve modern tüketici kuramının yolunu açmıştır.'),
  ('Sonnenschein-Mantel-Debreu sonucu genel denge kuramı için hangi sınırlamayı gösterir?', 'Dengenin kararlılığının garanti edilemediğini', ['Dengenin hiçbir koşulda var olamayacağını', 'Dengenin her zaman tek ve kararlı olduğunu', 'Piyasaların hiçbir zaman verimli sonuç vermediğini'], 'Bu sonuca göre bireysel rasyonel tercihlerden türeyen toplam talep fonksiyonu hemen hemen her biçimi alabilir; bu nedenle denge tekliği ve kararlılığı ek varsayım gerektirir.'),
  ('Wicksell\'in \'kümülatif süreç\' kuramı hangi sonucu doğurur?', 'Düşük piyasa faizinde fiyatların sürekli artması', ['Piyasa faizi doğal faizin üstündeyken enflasyon durmaksızın sürer', 'Piyasa ve doğal faiz her zaman otomatik olarak eşitlenir', 'Fiyatlar faizden bağımsız olarak hareket eder'], 'Piyasa faizi doğal faizin altında kalırsa yatırımlar tasarrufları aşar, talep ve fiyatlar kümülatif olarak yükselir; bu fikir modern para politikası kurallarının öncülüdür.'),
  ('Laspeyres endeksi 120, Paasche endeksi 108 ise Fisher\'in ideal endeksi yaklaşık kaçtır?', 'yaklaşık 113,8', ['yaklaşık 114,6', 'yaklaşık 112,0 puan', 'yaklaşık 116,5'], 'Fisher endeksi = √(120 × 108) = √12.960 ≈ 113,8 olur.'),
  ('Wicksell\'in kamu maliyesine katkısı olan \'oybirliği ilkesi\' neyi savunur?', 'Rıza ile kamusal finansmanı', ['Kamu harcamalarının tümüyle kapatılmasını', 'Vergilerin yalnızca zenginlerden alınmasını', 'Vergilerin yalnızca ithalattan toplanmasını'], 'Wicksell, vergilerin ve harcamaların birlikte karara bağlanıp mümkün olduğunca oybirliğine yaklaşılmasını savunarak sonradan kamu tercihi kuramına ilham vermiştir.'),
  ('Schumpeter\'in \'dolaşım akışı\' (circular flow) kavramı hangi durumu tanımlar?', 'Yenilik olmadığı, kâr ve faizin sıfıra yaklaştığı durağan dengeyi', ['Para arzının sürekli arttığı enflasyonist dönemi', 'Devletin bütçe fazlası verdiği dönemi', 'Dış ticaretin yalnızca ihracata dayandığı durumu'], 'Schumpeter\'e göre yenilik yokken ekonomi aynı üretimi tekrar eder; girişimci yeniliği bu akışı bozarak kâr elde eder ve gelişme başlar.'),
  ('Clément Juglar\'ın tespit ettiği iş döngüsü kaç yıllık yatırım dalgalarına karşılık gelir?', 'Yaklaşık 7-11 yıl', ['Yaklaşık 1-2 yıl', 'Yaklaşık 45-60 yıl', 'Yaklaşık 20-30 yıl'], 'Juglar, sabit sermaye yatırımına bağlı olarak 7-11 yıllık ticari krizler döngüsü olduğunu belirtmiştir; bu döngü \'ana\' iş döngüsü olarak anılır.'),
  ('Simon Kuznets\'in adıyla anılan 15-25 yıllık dalgalanmalar hangi etkenle ilişkilendirilir?', 'Konut ve altyapı yatırımı ile nüfus hareketleri', ['Merkez bankası faiz kararları ve kredi koşulları', 'Dış borç ödemeleri ve kur ayarlamaları', 'Tarım ürünü fiyatları ve hasat dönemleri'], 'Kuznets salınımları, inşaat ve altyapı yatırımlarının uzun süreli dalgaları olarak tanımlanır ve nüfus göçleriyle bağlantılıdır.'),
  ('Schumpeter\'e göre bir girişimcinin kâr elde etmesini sağlayan koşul nedir?', 'Yeniliğin geçici bir tekel konumu yaratması', ['Girişimcinin sermayesinin başkalarına göre daha büyük olması', 'Devletin girişimciye vergi muafiyeti vermesi', 'Piyasadaki tüm rakiplerin ortadan kaldırılması'], 'Yenilik rakiplerce taklit edilene kadar geçici bir tekel gücü ve yüksek kâr sağlar; yayılma süreci kârı aşındırır ve yeni yenilik gereksinimini doğurur.'),
  ('Veblen\'in marjinalist \'hedonist\' insan tasvirini eleştirirken kullandığı benzetme nedir?', 'Haz ve acıyı hesaplayan yıldırım hesapçı', ['Kendi çıkarını gözeten görünmez el benzeri bir ağ', 'Toprağına bağlı kalan ve hiç değişmeyen çiftçi', 'Piyasada kaybedeni olmayan sonsuz zengin tüccar'], 'Veblen, iktisatçıların insanı haz ve acıyı anında hesaplayan bir makine gibi gördüğünü, oysa davranışın alışkanlık ve kurumlarla biçimlendiğini savunmuştur.'),
  ('Galbraith\'in \'Yeni Sanayi Devleti\'nde (1967) tanımladığı \'teknoyapı\' (technostructure) nedir?', 'Uzman yöneticiler topluluğudur', ['Devletin teknolojiyi planlayan bakanlıklar topluluğudur', 'Hissedarların toplandığı genel kurul organıdır', 'İşçi sendikalarının yönetim kurullarıdır'], 'Galbraith\'e göre büyük şirketlerde güç hissedarlardan uzman yönetici ve mühendis ekibine geçmiştir; bu grup kâr kadar büyümeyi ve güvenliği de önemser.'),
  ('Polanyi\'nin \'çifte hareket\' (double movement) kavramı nasıl açıklanır?', 'Toplumun piyasaya karşı korunmasını', ['Mal ve para piyasalarının aynı anda genişlemesi', 'Dış ticaretin hem ihracat hem ithalat yoluyla artması', 'Fiyatların hem yukarı hem aşağı yönlü hareket etmesi'], 'Piyasa genişledikçe toplum emek, toprak ve paranın metalaşmasına karşı yasa ve kurumlarla korunma arar; böylece ikili bir hareket doğar.'),
  ('Polanyi\'nin iktisadi eylemin toplumsal ilişkiler içine \'gömülü\' olduğu (embeddedness) görüşü neye karşıdır?', 'Piyasayı toplumdan bağımsız bir alan sayan anlayışa', ['Ticaretin gelişmesine yönelik tüm vergi kısıtlarına', 'Kâr amacının hiçbir koşulda var olmadığı görüşüne', 'Parasal teorinin matematiğe dayanması gerektiği görüşüne'], 'Polanyi\'ye göre ekonomi, tarihsel olarak akrabalık, din ve siyaset içine gömülüdür; kendi kendini düzenleyen piyasa fikri tarihsel olarak istisnadır.'),
  ('Gunnar Myrdal\'ın \'birikimli nedensellik\' (cumulative causation) kavramı bölgesel eşitsizlikleri nasıl açıklar?', 'Zenginlerin öne geçip yoksulların geri kalmasını', ['Yoksul bölgeler kendiliğinden zengin bölgeleri yakalar', 'Ticaret tüm bölgeleri eşit ölçüde zenginleştirir', 'Eşitsizlik her zaman tek başına devlet kararlarıyla doğar'], 'Myrdal\'a göre sermaye, nitelikli işgücü ve yatırım zengin bölgelere akar; bu geri besleme süreci eşitsizliği artırır ve piyasa tek başına dengelemez.'),
  ('Keynes\'in 1926 tarihli \'Laissez-Faire\'in Sonu\' denemesinde savunduğu temel düşünce nedir?', 'Devletin bazı alanlarda sorumluluk alması gerektiği', ['Devletin ekonomiden tümüyle çekilmesi gerektiği', 'Piyasaların yalnızca özel girişimle kusursuz işleyeceği', 'Serbest ticaretin tek başına yoksulluğu bitireceği'], 'Keynes bu denemede laissez-faire\'in doğal bir yasa olmadığını, devletin yatırım ve istikrar konusunda bilinçli rol alması gerektiğini söylemiştir.'),
  ('Keynes\'in 1945-46\'da ABD ile yaptığı müzakere sonucu İngiltere\'ye sağlanan kaynak nedir?', 'ABD\'den alınan savaş sonrası kredi', ['Marshall Planı kapsamında verilen hibe', 'Dünya Bankası\'ndan alınan tarım kredisi', 'Altın karşılığı alınan sınırsız borç'], 'Keynes, savaş sonrası İngiliz ekonomisinin dış açığını kapatmak için ABD\'yle Anglo-Amerikan kredi anlaşmasını yürütmüştür; koşullar ağırdı ama ülkeye zaman kazandırdı.'),
  ('Keynes\'in \'hayvansal güdüler\' (animal spirits) kavramı yatırım kararlarında neyi vurgular?', 'Hesaplardan çok iyimser dürtülerin payını', ['Yatırımın yalnızca matematiksel kâr hesabına göre yapıldığını', 'Yatırım kararlarının devlet planıyla belirlendiğini', 'Yatırımcıların yalnızca faiz oranına bakıp karar verdiğini'], 'Keynes\'e göre belirsizlik karşısında yatırımcılar çoğu zaman gelecekteki getirilerin kesin hesabını değil, kendiliğinden doğan eyleme geçme eğilimini izler.'),
  ('Keynes\'in borsa yatırımcılarının davranışını anlatmak için kullandığı \'güzellik yarışması\' benzetmesi neyi gösterir?', 'Başkalarının beklentisini tahmin etmeyi', ['Yatırımcıların yalnızca şirketlerin bilançosuna bakmasını', 'Hisse fiyatının her zaman gerçek değere eşit olmasını', 'Yatırımcıların yalnızca uzun vadeli getiriyi önemsemesini'], 'Keynes, spekülatif piyasada yarışmacılar kendi beğenisine değil çoğunluğun beğeneceğini düşündükleri kişiye oy verdikleri gibi, hisse fiyatlarının da beklentilere dayandığını anlatır.'),
  ('Keynes\'in \'sermayenin marjinal verimliliği\' kavramı yatırımı nasıl etkiler?', 'Beklenen getiri oranı faiz oranının üzerindeyse yatırım yapılır', ['Beklenen getiri ne olursa olsun yatırım yalnızca devletçe yapılır', 'Beklenen getiri faiz oranının altındaysa yatırım artar', 'Yatırım yalnızca tasarruf oranına göre belirlenir'], 'Yatırımcı, bir yatırımın beklenen kârlılığını faiz oranıyla karşılaştırır; sermayenin marjinal verimliliği faizin üzerinde olduğu sürece yatırım artar.'),
  ('Keynes\'in \'istemsiz işsizlik\' kavramı nasıl tanımlanır?', 'Çalışmak isteyip iş bulamayanların işsizliği', ['İşçilerin yüksek ücret için gönüllü olarak çalışmayı bırakması', 'Mevsimlik işlerin sona ermesinden doğan geçici işsizlik', 'İşçilerin yeni iş ararken geçirdiği kısa bekleme dönemi'], 'Klasik iktisat gönüllü ve geçici işsizlikten başkasını kabul etmezken Keynes, talep yetersizliğinde ücret düzeyini kabul eden işçilerin de işsiz kalabileceğini göstermiştir.'),
  ('Keynes\'e göre ücretlerin düşürülmesi derin bir durgunlukta neden sorunu çözmeyebilir?', 'Talebi de düşürdüğü için', ['Ücretler düşünce tüketim kesinlikle artar', 'Ücret düşüşü yatırım maliyetini yükseltir', 'Ücret kesintisi yalnızca ihracatı artırır'], 'Bir işçinin ücreti başka birinin gelirini oluşturur; genel ücret düşüşü tüketimi azaltıp iş kaybını artırabilir, bu yüzden Keynes ücret esnekliğini çözüm görmemiştir.'),
  ('Keynes\'in \'rantiyenin ötanazisi\' (euthanasia of the rentier) ifadesi neyi önerir?', 'Faizi düşürüp kıtlık rantını azaltmayı', ['Toprak sahiplerinin mülklerine el konmasını', 'Emekli maaşlarının tümüyle kaldırılmasını', 'Yabancı yatırımcıların ülkeden çıkarılmasını'], 'Keynes, sermaye bolluğu arttıkça faizin düşmesini ve sermayenin kıtlık gelirinin kendiliğinden azalmasını umut etmiş; amaç sermayedarları ortadan kaldırmak değil kıtlık rantını azaltmaktı.'),
  ('Keynes\'in \'şişelere banknot doldurup kuyulara gömme\' önerisi neyi göstermek içindir?', 'Verimsiz harcamanın da talep yaratabileceğini', ['Kamu harcamalarının her zaman enflasyon yarattığını', 'Altının yeraltında saklanmasının en iyi yatırım olduğunu', 'Ücretlerin ancak madencilikle yükselebileceğini'], 'Keynes, madencilerin gömülü banknotları çıkarmak için istihdam edilmesi gibi bir düzenin bile durgunlukta gelir ve harcama yaratacağını, ancak yararlı kamu işlerinin daha iyi olacağını söylemiştir.'),
  ('Keynes\'e göre yatırımın kamu tarafından \'sosyalleştirilmesi\' ne anlama gelir?', 'Devletin yatırımda doğrudan rol alması', ['Üretim araçlarının tamamen kamulaştırılması', 'Yatırımın tümüyle yasaklanması', 'Yatırımın dışarıdan sermaye girişine bırakılması'], 'Keynes, özel yatırımın dalgalı olması nedeniyle kamunun yatırım hacmini düzenlemesini savunmuş; ama bu mülkiyetin devletleştirilmesi anlamına gelmez.'),
  ('Keynes\'in temel belirsizlik anlayışı, olasılık kuramına dayanan \'beklenen fayda\' yaklaşımından hangi bakımdan ayrılır?', 'Bazı geleceklerin olasılığının hesaplanamayacağını kabul etmesiyle', ['Gelecekteki olayların her zaman kesin olasılıklarla hesaplanabilmesiyle', 'Beklentilerin iktisadi kararlarda hiç rol oynamadığını varsaymasıyla', 'Faydanın ölçülebilir ve toplanabilir olduğunu savunmasıyla'], 'Keynes, \'Olasılık Üzerine İnceleme\' (1921) ve Genel Teori\'de ortaya koyduğu temel belirsizlik fikriyle, geleceğin birçok boyutunda olasılık hesabı yapılamayacağını söylemiştir.'),
  ('Abba Lerner\'in 1943\'te önerdiği \'işlevsel maliye\' (functional finance) ilkesi neyi savunur?', 'Bütçeyi değil istihdamı hedefleyen maliye', ['Bütçenin her yıl mutlaka dengede tutulmasını', 'Vergilerin yalnızca ithalattan alınmasını', 'Kamu harcamalarının her koşulda azaltılmasını'], 'Lerner\'e göre maliye politikası bütçeyi dengelemek için değil, harcama düzeyini ekonominin gereksinimine göre ayarlamak için kullanılmalıdır.'),
  ('Don Patinkin\'in 1956 tarihli \'Para, Faiz ve Fiyatlar\' kitabında vurguladığı etki hangisidir?', 'Reel bakiyeler etkisinin modele katılması', ['Çarpan etkisi', 'Dış ticaret çarpanı etkisi', 'Dışlama etkisi'], 'Patinkin, fiyatlar düştüğünde reel para stokunun artıp harcamayı artıracağı fikriyle klasik ve Keynesyen kuramı birleştirmeye çalışmıştır.'),
  ('Samuelson ile Solow\'un 1960 tarihli çalışmasında Phillips eğrisi hangi biçimde yorumlanmıştır?', 'Enflasyon-işsizlik tercih menüsü olarak', ['Enflasyon ile işsizliğin aynı yönde hareket ettiğini gösteren bir bağ olarak', 'Yalnızca uzun dönemde geçerli olan sabit bir doğru olarak', 'Para arzı ile faiz arasındaki ilişkinin grafiği olarak'], 'Samuelson ve Solow, ABD verilerine uyarladıkları Phillips eğrisini, hükümetin seçebileceği enflasyon-işsizlik bileşimleri olarak sunmuş; bu yorum sonradan eleştirilmiştir.'),
  ('Alvin Hansen\'in ABD\'de Keynes\'i yaygınlaştırırken öne sürdüğü \'ebedî durgunluk\' (secular stagnation) tezi neyi anlatır?', 'Uzun dönemli durgunluk riskini', ['Sürekli aşırı ısınan ekonomilerde enflasyon riskini', 'Dış ticaret fazlasının sonsuza kadar artışını', 'Kamu borcunun kendiliğinden sıfırlanmasını'], 'Hansen, 1938\'de nüfus artışının yavaşlaması ve yatırım fırsatlarının azalmasıyla ekonomilerin uzun süreli talep yetersizliğiyle karşılaşabileceğini savunmuştur.'),
  ('James Tobin\'in 1958\'de likidite tercihi üzerine yazdığı makale Keynes\'in kuramına neyi eklemiştir?', 'Riskten kaçınma ile portföy seçimine', ['Altın standardına dönüş gerekçesini', 'Yeni bir üretim fonksiyonu biçimini', 'Dış ticaret çarpanı formülünü'], 'Tobin, yatırımcıların getiri ve risk arasında portföylerini dağıttığını göstererek para talebini mikro temelli bir risk davranışı olarak açıklamıştır.'),
  ('Neoklasik sentezin temel iddiası aşağıdakilerden hangisidir?', 'Kısa dönemde Keynesyen talep yönetimi, uzun dönemde neoklasik piyasa işleyişi geçerlidir', ['Hem kısa hem uzun dönemde yalnızca talep belirleyicidir ve arz önemsizdir', 'Hem kısa hem uzun dönemde devlet müdahalesi yararsızdır', 'Hem kısa hem uzun dönemde fiyatlar tamamen sabittir'], 'Sentez, tam istihdam yakınında klasik, işsizlik koşullarında Keynesyen çözümlemeyi geçerli sayarak iki yaklaşımı tek çerçevede birleştirmiştir.'),
  ('Joan Robinson\'ın \'sahte Keynesçilik\' (bastard Keynesianism) dediği şey nedir?', 'Keynes\'in öğretisinin yanlış yorumlanması', ['Keynes\'in sosyalist görüşlerini öne çıkaran yorum', 'Keynes\'in dış ticaret kuramını bozan yorum', 'Keynes\'in tüm kuramını matematikten arındıran yorum'], 'Robinson, neoklasik sentezin Keynes\'in köklü yeniliklerini seyreltip eski dengelere indirgediğini düşünerek bu yorumu \'sahte\' olarak adlandırmıştır.'),
  ('Neoklasik sentez döneminde (1950-60\'lar) ABD\'de ekonomi politikasına hangi anlayış egemen olmuştur?', 'Talep yönetimi ve ince ayar', ['Altın standardına tam dönüş ve bütçe kısıtlaması', 'Arz yönlü vergi indirimleri ve özelleştirme', 'Fiyat-ücret kontrolleriyle tam planlama'], 'Kennedy-Johnson döneminin ekonomik danışmanları maliye ve para politikasını kullanarak tam istihdamı sürdürmeyi hedefleyen \'ince ayar\' anlayışını benimsemiştir.'),
  ('Cambridge sermaye tartışmasında \'yeniden anahtarlama\' (reswitching) sonucu neyi gösterdi?', 'Faizle teknik seçiminin her zaman tek yönlü olmadığını', ['Sermayenin hiçbir zaman ölçülemediğini ve faizin olmadığını', 'Dış ticaretin her zaman kazanç sağladığını', 'Para arzının fiyatları değiştirmediğini'], 'Sraffacı çözümlemede aynı tekniğin faiz değiştikçe yeniden kârlı hale gelebileceği gösterilmiş; bu, neoklasik toplam üretim fonksiyonu fikrine ciddi bir itiraz olmuştur.'),
  ('Post-Keynesyen \'içsel para\' görüşüne göre banka kredisi ve para arzı nasıl belirlenir?', 'Talebe uyan kredi, faizi merkez bankası saptar', ['Merkez bankasının sabit olarak belirlediği dışsal bir miktar olarak', 'Altın stokuna doğrudan bağlı bir miktar olarak', 'Devletin her yıl bütçeye göre sabitlediği bir miktar olarak'], 'Kaldor ve Moore gibi yazarlara göre bankalar talebi karşılar, merkez bankası ise rezerv sağlayıp faizi belirler; para arzı dışsal değil içseldir.'),
  ('George Shackle\'ın \'çarpıcı kararlar\' (crucial decisions) ile ilgili düşüncesi neyi vurgular?', 'Tekrarlanamaz benzersiz olaylara dayandığını', ['Kararların daima tam bilgiyle alındığını', 'Beklentilerin hiçbir rol oynamadığını', 'Kararların yalnızca geçmiş verilere dayandığını'], 'Shackle, girişimci kararlarının tekrarlanamayan benzersiz durumlar olduğunu belirtip olasılık dağılımlarının yetersiz olduğunu savunmuştur.'),
  ('Post-Keynesyen iktisadın neoklasik sentezden ayrıldığı temel nokta hangisidir?', 'Belirsizlik, para ve talebin uzun dönemde belirleyiciliği', ['Piyasaların her koşulda kendiliğinden dengeye geldiği görüşü', 'Para arzının yalnızca fiyatları etkilediği görüşü', 'Ücretlerin tamamen esnek olduğu görüşü'], 'Post-Keynesyenler Keynes\'in temel belirsizlik, para ve etkin talep fikirlerini uzun döneme taşıyıp denge varsayımlarını reddeder.'),
  ('Friedman\'ın 1968\'de Amerikan İktisat Derneği başkanlık konuşmasında Phillips eğrisine yönelttiği temel eleştiri nedir?', 'İşsizliğin uzun dönemde doğal orana döndüğü', ['Enflasyon ile işsizliğin kalıcı biçimde aynı yönde hareket ettiği', 'Para arzının işsizliği kalıcı olarak sıfıra indirebileceği', 'Faiz oranlarının işsizlikle hiçbir ilişkisinin bulunmadığı'], 'Friedman ve Phelps, işçiler enflasyonu öngördüğünde kısa dönemli işsizlik azalışının kaybolduğunu, uzun dönemde dikey bir Phillips eğrisi bulunduğunu savunmuştur.'),
  ('Friedman\'ın 1953 tarihli \'Pozitif İktisadın Yöntemi\' makalesindeki ünlü tezi nedir?', 'Kuram tahmin gücüne göre sınanır', ['Varsayımlar her zaman gerçeğe birebir uymalıdır', 'İktisat kuramı yalnızca ahlaki ilkelere dayanmalıdır', 'Tahmin yeteneği kuramın değerlendirilmesinde önemsizdir'], 'Friedman\'a göre bir kuramın varsayımları gerçekçi olmasa da (\'sanki\' davranıyormuş gibi) iyi tahmin yapıyorsa yararlıdır; bu tez uzun süren yöntem tartışmasına yol açmıştır.'),
  ('Friedman\'ın savunduğu \'negatif gelir vergisi\' önerisi neyi amaçlar?', 'Düşük gelirlilere nakit destek vermeyi', ['Zenginlerin gelirinden yüzde yüz vergi almayı', 'Tüm vergileri kaldırıp yalnızca tüketime vergi koymayı', 'Düşük gelirlilerden daha yüksek oranda vergi almayı'], 'Vergi eşiğinin altında kalan kişilere devlet ödeme yapar; Friedman bunu yardım programlarının karmaşıklığını azaltmanın yolu olarak görmüştür.'),
  ('Henry Simons\'ın 1934 tarihli \'Laissez-Faire için Olumlu Bir Program\' yazısı hangi anlayışı yansıtır?', 'Rekabeti koruyan kurallı devlet', ['Devletin tümüyle ortadan kalkması', 'Üretim araçlarının devletleştirilmesi', 'Sendikaların yasaklanıp piyasaların kapatılması'], 'Simons, tekelleri kıran ve para kurallarını belirleyen devletle serbest piyasayı birleştirmeyi savunmuş; erken Chicago anlayışının önemli yazarıdır.'),
  ('George Stigler\'in \'düzenleyici ele geçirme\' (regulatory capture) görüşü neyi öne sürer?', 'Düzenleyicinin sektörün çıkarına çalışması', ['Düzenlemenin her zaman tüketici lehine işlediğini', 'Düzenlemenin hiçbir zaman sektörü etkilemediğini', 'Düzenleyici kurumların yalnızca ordu tarafından yönetildiğini'], 'Stigler, sanayinin kamu otoritesini kendi çıkarına yönlendirebildiğini göstermiş; bu yaklaşım kamu tercihi yazınında etkili olmuştur.'),
  ('Friedman\'ın okul çeki (voucher) önerisi neyi amaçlar?', 'Ailelerin okul seçmesini', ['Okulların tümünü kamulaştırmayı', 'Eğitimi paralı ve devlet destekli olmayan hale getirmeyi', 'Öğretmen maaşlarını sabitlemeyi'], 'Devlet eğitim harcamasını aileye çek olarak verir; aile çeki kamu ya da özel okulda kullanır, böylece okullar öğrenci için rekabet eder.'),
  ('Yeni klasik iktisadın \'piyasaların sürekli temizlendiği\' varsayımı hangi sonuca götürür?', 'Dalgalanmaların beklenmedik şoklara bağlanmasına', ['Her işsizliğin talep yetersizliğinden doğduğuna', 'Piyasaların hiçbir zaman dengeye gelmediğine', 'Fiyatların daima sabit kaldığına'], 'Piyasalar sürekli dengedeyse işsizlik ve üretim dalgalanmaları gönüllü karar değişikliği ve algılama hatalarıyla açıklanır; talep yönetimi politikalarının rolü sınırlı kalır.'),
  ('Blanchard ve Summers\'ın \'histerezis\' kavramı işsizlik için ne anlatır?', 'Kalıcı yüksek işsizlik bırakabileceğini', ['İşsizliğin kendiliğinden sıfıra düşeceğini', 'İşsizliğin yalnızca mevsimlik olduğunu', 'İşsizliğin faizle ilgisinin bulunmadığını'], 'Uzun süreli işsizlik beceri kaybı ve çalışanların pazarlık gücü nedeniyle doğal oranı kalıcı olarak yükseltebilir.'),
  ('1986 Vergi Reformu Yasası\'nda ABD\'nin en yüksek bireysel gelir vergisi oranı kaç yüzde olmuştur?', 'Yüzde 28', ['Yüzde 50', 'Yüzde 39', 'Yüzde 15'], 'Reagan döneminin vergi reformu oranları düşürüp kapsamı genişletmiş; en üst bireysel oran yüzde 28\'e inmiştir.'),
  ('Thatcher hükümetinin 1979\'da yaptığı ilk bütçede İngiltere\'de en yüksek gelir vergisi oranı ne olmuştur?', 'Yüzde 83\'ten yüzde 60\'a', ['Yüzde 60\'tan yüzde 83\'e çıkarılmıştır', 'Yüzde 40\'tan yüzde 20\'ye indirilmiştir', 'Yüzde 98\'den yüzde 98\'de bırakılmıştır'], 'Maliye Bakanı Geoffrey Howe 1979\'da en yüksek oranı yüzde 83\'ten yüzde 60\'a, KDV\'yi ise yükseltmiştir; oran 1988\'de yüzde 40\'a inmiştir.'),
  ('Arz yanlı iktisadın eleştirmenleri Reagan dönemi için hangi sonucu öne sürmüştür?', 'Açığın büyüdüğünü', ['Vergi gelirleri indirimler sonucu sürekli arttı', 'Bütçe açığı hızla kapanıp fazlaya geçti', 'Kamu borcu sıfırlandı'], 'Vergi indirimleri ve artan savunma harcamaları 1980\'lerde federal bütçe açığını ve kamu borcunu önemli ölçüde artırmıştır.'),
  ('\'Damlama etkisi\' (trickle-down) tezi neyi savunur?', 'Üst vergi indiriminin herkese yayılmasını', ['Alt gelir gruplarına verilen yardımların üst gruplara yayılacağını', 'Kamu harcamasının kendiliğinden azalacağını', 'İthalatın yurt içi üretimi artıracağını'], 'Tez, zenginlerin vergi indirimleriyle yaptığı yatırım ve istihdamın aşağıya doğru sızarak tüm toplumu zenginleştireceğini savunur; eleştirmenleri kanıt eksikliğine işaret eder.'),
  ('Harold Demsetz\'in mülkiyet haklarının doğuşuna ilişkin görüşü nedir?', 'Değer arttıkça özel mülkiyetin yaygınlaşması', ['Mülkiyet hakları hiçbir koşulda tanımlanmaz', 'Mülkiyet yalnızca devletin kararıyla başlar', 'Mülkiyet hakları değeri düşük kaynaklar için ortaya çıkar'], 'Demsetz\'e göre yeni bir kaynağın değeri yükselince dışsallıkları içselleştirmenin yararı maliyeti aşar ve özel mülkiyet kurumsallaşır.'),
  ('Logrolling (oy alışverişi) kavramı kamu tercihi yazınında neyi anlatır?', 'Karşılıklı destekle oy takasını', ['Seçmenlerin hiç oy kullanmamasını', 'Bakanların bütçeden ödenek almamasını', 'Hükümetin yalnızca kamu hizmeti sunmasını'], 'Oy alışverişi, her temsilcinin kendi bölgesine yarar sağlayan projeleri birbirinin lehine oylamasıdır; kamu harcamalarının artmasına yol açabilir.'),
  ('Kahneman ve Tversky\'nin 1974 tarihli makalesinde \'çıpalama\' (anchoring) neyi anlatır?', 'İlk sayının tahmini etkilemesini', ['Tahminlerin her zaman gerçek değere eşit olmasını', 'Yatırımcının yalnızca devlet tahvili almasını', 'İnsanların fiyat bilgisini hiç dikkate almamasını'], 'Kişiler belirsiz bir nicelik tahmin ederken, ilgisiz bile olsa elde bulunan bir başlangıç değerine bağlı kalıp tahminlerini yeterince uzaklaştırmaz.'),
  ('Kayıptan kaçınma (loss aversion) bulgusuna göre aynı büyüklükteki kayıp ve kazanç karşısında insanlar nasıl davranır?', 'Kaybın acısını daha ağır duyar', ['Kazancın hazzını kaybın acısından daha ağır duyar', 'İkisine de aynı ağırlık verir', 'İkisini de hiç dikkate almaz'], 'Beklenti kuramında değer fonksiyonu kayıp bölgesinde daha diktir; deneylerde kaybın ağırlığı kazancın yaklaşık iki katı bulunmuştur.'),
  ('Thaler\'in \'sahip olma etkisi\' (endowment effect) kavramı neyi gösterir?', 'Sahip olunana daha çok değer biçilmesini', ['İnsanların sahip olduğu şeyi hemen satmak istemesini', 'İnsanların hiçbir şeye değer biçmemesini', 'Fiyatların daima maliyete eşit olmasını'], 'Kahneman, Knetsch ve Thaler\'in kupa deneylerinde, kupayı elinde tutanlar satmak için almak isteyenlerin ödemek istediğinden çok daha yüksek fiyat istemiştir.'),
  ('Thaler\'in \'zihinsel muhasebe\' (mental accounting) kavramına göre insanlar parayı nasıl kullanır?', 'Parayı kaynağına ve amacına göre ayrı hesaplarda tutarak', ['Bütün parayı tek bir hesapta aynı biçimde değerlendirerek', 'Parayı tamamen harcayıp hiç saklamayarak', 'Parayı yalnızca altın olarak biriktirerek'], 'Kişiler parayı \'ikramiye\', \'maaş\' gibi kategorilere ayırıp farklı davrandığı için, ikramiyeyi maaştan daha kolay harcayabilir.'),
  ('Zamanla tutarsız tercihleri açıklayan \'hiperbolik iskonto\' neyi söyler?', 'Yakın sabırsızlığın çok yüksek olmasını', ['Sabırsızlığın zaman boyunca sabit kaldığını', 'Bugünün tüketimine hiç değer verilmediğini', 'Yalnızca uzak gelecek için karar alındığını'], 'Kişi bugünle yarın arasında sabırsızken, bir yıl sonra ile bir yıl ve bir gün sonra arasında sabırlıdır; bu yüzden planlarını sonradan bozar.'),
  ('Ellsberg paradoksu (1961) hangi davranış eğilimini gösterir?', 'Belirsiz olasılıklı seçeneklerden kaçınma', ['Riskli seçeneklere her zaman yönelme', 'Seçenekleri hesaba katmadan rastgele karar verme', 'Yalnızca küçük miktarlara bahis yapma'], 'İnsanlar olasılığı bilinen riske, belirsiz olasılıklı bahse tercih eder; bu davranış öznel beklenen fayda kuramıyla çelişir.'),
  ('Barro ve Sala-i-Martin\'in çalışmalarında \'koşullu yakınsama\' neyi anlatır?', 'Benzer ülkelerin kararlı duruma yakınsaması', ['Bütün ülkelerin aynı gelire ulaşmasını', 'Zengin ülkelerin sürekli daha hızlı büyümesini', 'Ülkelerin hiçbir koşulda yakınsamamasını'], 'Ülkelerin tasarruf, nüfus ve eğitim gibi özellikleri farklıysa farklı kararlı durumlara yakınsar; mutlak yakınsama ise veriyle çoğu zaman uyuşmaz.'),
  ('Alexander Gerschenkron\'un \'göreli geri kalmışlığın avantajı\' tezi nedir?', 'Geç kalanın banka ve devletle atılım yapması', ['Geç sanayileşen ülkelerin her zaman daha yavaş büyümesi', 'Sanayileşmenin tek bir yol izlemesi', 'Geri kalmışlığın hiçbir koşulda aşılamaması'], 'Gerschenkron\'a göre geç kalan ülkeler ileri teknolojiyi ödünç alıp bankalar veya devlet kurumları aracılığıyla hızlı yatırım yapabilir.'),
  ('Büyüme muhasebesi çalışmalarında Edward Denison\'ın ABD verilerinden elde ettiği vurgu nedir?', 'Verimlilik ve eğitimin payının büyüklüğü', ['Büyümenin yalnızca para arzına bağlı olduğu', 'Büyümenin yalnızca doğal kaynaklardan geldiği', 'Büyümenin yalnızca nüfus artışıyla açıklandığı'], 'Denison\'un çalışmaları, çıktı büyümesinin yalnızca girdi artışıyla açıklanamadığını, eğitim ve ölçek ekonomileri gibi etkenlerin de önemli olduğunu göstermiştir.'),
  ('Paul Rosenstein-Rodan\'ın 1943 tarihli \'büyük itiş\' (big push) tezi neyi savunur?', 'Tamamlayıcı yatırımların birlikte yapılmasını', ['Her yatırımın tek tek ve yavaşça yapılması gerektiğini', 'Yalnızca tarıma yatırım yapılmasını', 'Dış yardımın tümüyle reddedilmesini'], 'Rosenstein-Rodan\'a göre bağımsız küçük yatırımlar pazar genişliği sorunu nedeniyle kârlı olmaz; birbirini tamamlayan yatırımlar birlikte yapılırsa talep yaratılır.'),
  ('Dani Rodrik\'in \'tek iktisat, çok reçete\' görüşü ne söyler?', 'Aynı iktisat kuramı farklı ülke koşullarında farklı politika çözümleri gerektirir', ['Her ülke aynı reçeteyi uygulamalıdır', 'Ülke koşullarının hiçbir önemi yoktur', 'Reçeteler yalnızca zengin ülkeler için geçerlidir'], 'Rodrik, genel kuramın yerel kısıtlara uyarlanması gerektiğini, Washington Uzlaşması gibi tek tip reçetelerin yetersiz kaldığını savunur.'),
  ('Jeffrey Sachs\'ın \'yoksulluk tuzağı\' yaklaşımı kalkınma yardımı için hangi sonucu savunur?', 'Büyük hedefli yardımın tuzaktan çıkaracağını', ['Yardımın her koşulda zarar verdiğini', 'Yardımın yalnızca özel bankalarca yapılması gerektiğini', 'Yoksul ülkelerin kendi başına zenginleşeceğini'], 'Sachs, düşük gelirli ülkelerin tasarruf yapamayacak kadar yoksul olduğunu, dışarıdan yeterli kaynak sağlanırsa kalkınmanın başlayabileceğini savunmuştur.'),
  ('William Easterly\'nin \'Beyaz Adamın Yükü\' kitabı kalkınma yardımına hangi eleştiriyi yöneltir?', 'Büyük planlı yardımın sonuç vermediğini', ['Yardımın hiç yapılmaması gerektiğini', 'Yardımın yalnızca gümrük indirimiyle olması gerektiğini', 'Yardımın tümüyle bankalardan alınmasının zorunlu olduğunu'], 'Easterly, \'planlamacılar\' ile \'arayıcılar\' ayrımıyla, yerel geri bildirimle çalışan küçük çözümleri büyük planlara tercih eder.'),
  ('Chang\'ın \'Merdiveni Tekmelemek\' (2002) kitabının savı nedir?', 'Zenginlerin korumacılık merdivenini yoksullara yasaklamasını', ['Zengin ülkelerin hiç korumacılık yapmadığıdır', 'Yoksul ülkelerin yalnızca tarıma odaklanması gerektiğidir', 'Küreselleşmenin her zaman refahı artırdığıdır'], 'Chang, İngiltere ve ABD gibi ülkelerin gümrük koruması ve sübvansiyonla sanayileştiğini, ardından serbest ticareti öğütlediklerini belirtir; List\'in savına yakın bir yaklaşımdır.'),
  ('Andre Gunder Frank\'in 1966\'da \'azgelişmişliğin gelişimi\' tezi neyi savunur?', 'Kapitalist sisteme bağlanmanın ürünü olduğunu', ['Azgelişmişliğin ilkel bir başlangıç hâli olduğunu', 'Azgelişmişliğin yalnızca kültürel nedenlerden geldiğini', 'Azgelişmişliğin yalnızca coğrafya kaynaklı olduğunu'], 'Frank\'e göre çevre ülkeler hiçbir zaman \'geleneksel\' bir başlangıçta kalmamış, merkezle sömürü ilişkisi içinde sürekli azgelişmiş kılınmıştır.'),
  ('Cardoso ve Faletto\'nun 1969 tarihli çalışmasında \'ilişkili bağımlı kalkınma\' kavramı neyi anlatır?', 'Bağımlı ülkelerde de birikimin sürdüğünü', ['Bağımlı ülkelerde hiç büyüme olmayacağını', 'Bağımlı ülkelerin merkezi tümüyle yok edebileceğini', 'Yalnızca tarımsal üretimin sürebileceğini'], 'Cardoso ve Faletto, bağımlılığın büyümeyi tümüyle engellemediğini ama biçimini ve yönünü belirlediğini göstermişlerdir.'),
  ('Ithal ikameci sanayileşme (İİS) stratejisinin Latin Amerika\'da 1950-70 arasındaki temel sakıncalarından biri neydi?', 'Korunan sanayinin verimsizliği ve ithalat bağı', ['Sanayinin tamamen ihracata dönmesi', 'Hammadde üretiminin hızla artması', 'Ülkelerin dış ticaretinin sıfırlanması'], 'Yüksek gümrük ve kur politikaları sanayi için talep yaratsa da verimlilik ve ihracat artışı zayıf kaldığından döviz darboğazı doğmuştur.'),
  ('Samir Amin\'in \'eşitsiz değişim\' görüşü neyi öne sürer?', 'Ücret farkıyla değer transferini', ['Çevre ülkelerin merkeze her zaman değer aktardığı gerçeğini inkâr eder', 'Ticaretin her zaman eşit olduğunu', 'Gelir farklarının yalnızca para arzına bağlı olduğunu'], 'Amin ve Emmanuel\'e göre ücretler çevrede düşük ve merkezde yüksek olduğu için ticaret yoluyla çevreden merkeze değer akar.'),
  ('Celso Furtado\'nun Brezilya ekonomisi üzerine çalışmalarında vurguladığı temel konu nedir?', 'Dış talebe bağlı büyümenin sınırlarını', ['Altın standardının üstünlüğü', 'Merkezi planlamanın tümüyle gereksizliği', 'Dış borcun hiçbir zaman sorun olmadığı'], 'Furtado, Brezilya\'daki tarıma dayalı ihracat modelinin sanayileşmeyi sınırladığını ve kuzeydoğu-güneydoğu farkını açıkladığını belirtmiştir.'),
  ('1980\'lerde IMF ve Dünya Bankası\'nın borçlu ülkelere dayattığı \'yapısal uyum programları\' hangi yönde reformlar içerir?', 'Kısma, dış ticaret serbestliği, özelleştirme', ['Üretimi kamulaştırma ve kur sabitleme', 'Dış ticareti yasaklama ve ithalatı artırma', 'Para basımını artırma ve faizleri sıfırlama'], 'Programlar bütçe disiplini, ticaret liberalizasyonu ve kamu işletmelerinin özelleştirilmesini öngörmüş; sosyal maliyetleri nedeniyle eleştirilmiştir.'),
  ('Scitovsky paradoksu Kaldor-Hicks ölçütünün hangi zayıflığını gösterir?', 'İki yönlü geçişin de iyileşme sayılabilmesini', ['Hiçbir değişikliğin karşılaştırılamamasını', 'Pareto ilkesinin her zaman yetersiz olmasını', 'Tazminatın her zaman ödenmesini'], 'Scitovsky, iki durumun da birbirine göre tazminat testini geçebileceğini göstererek ölçütün tutarsızlığına dikkat çekmiştir.'),
  ('Atkinson endeksi eşitsizlik ölçümünde Gini katsayısından nasıl ayrılır?', 'Değer yargısını parametreyle içermesi', ['Hiç veri gerektirmez', 'Yalnızca servet dağılımını ölçer', 'Her zaman 1\'e eşittir'], 'Atkinson endeksi, toplumun eşitsizlikten duyduğu rahatsızlığı bir parametreyle yansıtarak eşit paylaşıma denk gelen gelir düzeyini ölçer.'),
  ('Fogel ve Engerman\'ın 1974 tarihli \'Haçta Zaman\' (Time on the Cross) kitabının tartışmalı savı nedir?', 'Güney\'deki köleliğin verimli olduğu', ['Kölelik ekonomik olarak hep zararlıydı', 'Kölelik yalnızca Kuzey\'de yaygındı', 'Kölelik tarım dışında hiç görülmedi'], 'Kitap kölelik ekonomisinin kârlı ve verimli çalıştığını, ancak ahlaki olarak kabul edilemez olduğunu savunmuştur; yöntem ve sonuçlar çok tartışılmıştır.'),
  ('Fernand Braudel\'in \'uzun süre\' (longue durée) kavramı tarih yazımında neyi vurgular?', 'Yapı ve coğrafya gibi yavaş etkenleri', ['Yalnızca tek günlük siyasi olayları', 'Yalnızca savaş ve antlaşmaları', 'Yalnızca bireylerin yaşam öykülerini'], 'Braudel, \'Akdeniz\' kitabında olaylar, konjonktürler ve uzun süreli yapılar şeklinde üç zaman katmanı ayırarak iktisat tarihini yeni bir çerçeveye oturtmuştur.'),
  ('Kenneth Pomeranz\'ın \'Büyük Ayrışma\' (2000) kitabı Avrupa ve Çin arasındaki farkın kaynağını nasıl açıklar?', 'Kömür ve sömürge kaynaklarıyla', ['Avrupalıların doğuştan daha çalışkan olmasıyla', 'Çin\'in tüm ticareti yasaklamasıyla', 'Avrupa\'nın daha fazla nüfusuyla'], 'Pomeranz, 18. yüzyıla kadar Çin\'in en gelişmiş bölgeleri ile Avrupa arasında büyük fark bulunmadığını, sonradan kömür ve Amerika kaynaklarının Avrupa\'yı öne çıkardığını savunur.'),
  ('David Landes\'in \'Ulusların Zenginliği ve Yoksulluğu\' (1998) kitabı kalkınma farklarını nasıl açıklar?', 'Kültür ve kurumların rolüyle', ['Yalnızca madenlerin bulunmasıyla', 'Yalnızca sömürgecilik gelirleriyle', 'Yalnızca iklimin sıcaklığıyla'], 'Landes, bilgi, çalışma ahlakı ve siyasal kurumların uzun dönemli büyümedeki belirleyiciliğine dikkat çeker; coğrafya ve kültür tartışmasında kültürcü kanatta yer alır.'),
  ('Robert Allen\'ın İngiliz Sanayi Devrimi\'ni açıklayan \'yüksek ücret, ucuz enerji\' tezi neyi öne sürer?', 'Pahalı emek, ucuz kömürün makineleşmeyi kârlı kılması', ['İngiltere\'de ücretlerin çok düşük olduğunu', 'Kömürün çok pahalı olduğunu', 'Makinelerin kârsız olduğunu'], 'Allen\'a göre emeğin görece pahalı, enerjinin ucuz olması yenilikleri İngiltere\'de kârlı kılmış; aynı teknoloji düşük ücretli ülkelerde yayılmamıştır.'),
  ('Barry Eichengreen\'in \'Altın Prangalar\' (1992) kitabının Büyük Buhran açıklaması nedir?', 'Altın bağlılığının krizi derinleştirmesi', ['Altın standardından erken çıkılmasının krizi yarattığı', 'Gümüş standardının yetersizliğinin krize neden olduğu', 'Merkez bankalarının çok sayıda altın sattığı'], 'Eichengreen, altın standardını erken terk eden ülkelerin daha çabuk toparlandığını, bağlı kalanların derin deflasyon yaşadığını göstermiştir.'),
  ('Barkan\'ın 16. yüzyıl Osmanlı\'daki fiyat hareketlerine ilişkin çalışması neyi göstermiştir?', 'Osmanlı\'nın fiyat devriminden etkilendiğini', ['Osmanlı\'nın fiyat artışlarından hiç etkilenmediğini', 'Fiyatların yüzyıl boyunca düştüğünü', 'Fiyat artışlarının yalnızca kıtlıktan geldiğini'], 'Barkan, Amerikan gümüşünün ve nüfus artışının Osmanlı fiyatlarını yükselttiğini göstererek Osmanlı\'nın dünya ekonomisiyle bağlantısını ortaya koymuştur.'),
  ('İktisatçı Halil İnalcık\'ın Osmanlı ekonomisine ilişkin çalışmalarında öne çıkan vurgu nedir?', 'Hem devlet denetimine hem ticarete bağlı yapı', ['Osmanlı\'nın tümüyle kapalı bir ekonomi olduğu', 'Osmanlı\'da hiç ticaret yapılmadığı', 'Osmanlı\'nın yalnızca madencilikle geçindiği'], 'İnalcık, Osmanlı\'da devletin piyasa üzerindeki rolü ile Akdeniz ve Karadeniz ticaretinin önemini birlikte ele almıştır.'),
  ('Ahilik teşkilatında yerel esnaf birliğinin başında bulunan ve seçimle gelen yönetici hangi adla anılırdı?', 'Ahi Baba', ['Kethüda paşa', 'Sadrazam', 'Muhtesip ağa'], 'Ahi birliklerinde zanaat kolunun başındaki kişiye Ahi Baba denir; çırak, kalfa ve ustaların yetişmesini ve ahlaki kurallara uyumu gözetirdi.'),
  ('Nicholas Georgescu-Roegen\'in 1971 tarihli \'Entropi Yasası ve Ekonomik Süreç\' kitabının temel savı nedir?', 'Süreçlerin düşük entropili kaynak tüketmesi', ['Ekonomik büyümenin hiçbir fiziksel sınırı olmadığı', 'Enerjinin üretimde hiçbir rol oynamadığı', 'Atıkların her zaman sıfıra geri dönüştürülebileceği'], 'Georgescu-Roegen\'e göre üretim, kullanılabilir enerjiyi ve maddeyi geri dönüşümü olmayan biçimde dağıtır; bu nedenle sonsuz büyüme fiziksel olarak sürdürülemez.'),
  ('Herman Daly\'nin \'durağan hâl ekonomisi\' (steady-state economy) önerisi neyi savunur?', 'Ölçeğin ekolojik sınırlarda sabitlenmesini', ['Üretimin her yıl yüzde on artırılmasını', 'Doğal kaynakların sınırsız tüketilmesini', 'Ticaretin tümüyle durdurulmasını'], 'Daly, ekonominin biyosferin içinde bir alt sistem olduğunu ve fiziksel ölçeğinin sürdürülebilir düzeyde sabitlenmesi gerektiğini savunur.'),
  ('Daly\'nin sürdürülebilirlik kurallarından biri yenilenebilir kaynaklar için neyi öngörür?', 'Kullanım hızının yenilenmeyi aşmamasını', ['Kullanım hızının yenilenme hızının iki katı olmasını', 'Kullanımın tümüyle yasaklanmasını', 'Kullanımın yalnızca zenginlerce yapılmasını'], 'Kural, balık stoku ya da orman gibi yenilenebilir kaynakların yenilenme kapasitesinin altında kullanılmasını ister.'),
  ('Kenneth Boulding\'in 1966\'daki \'Uzay Gemisi Dünya\' benzetmesi neyi anlatır?', 'Dünya\'nın kapalı ve sınırlı olduğunu', ['Dünya\'nın sonsuz bir kaynak deposu olduğunu', 'Teknolojinin tüm sınırları kaldıracağını', 'Uzay yolculuğunun ekonomik büyümeyi sağlayacağını'], 'Boulding, \'kovboy ekonomisi\'ni sınırsız kaynak varsayımıyla, \'uzay gemisi ekonomisi\'ni ise geri dönüşüm ve sınırlı kaynak varsayımıyla karşılaştırmıştır.'),
  ('Costanza ve arkadaşlarının 1997 tarihli çalışması hangi konuda yaygın biçimde alıntılanır?', 'Ekosistem hizmetlerinin değer tahminini', ['Altın rezervlerinin dağılımının hesaplanması', 'Dünya nüfus artışının tahmini', 'Küresel ticaret açıklarının ölçülmesi'], 'Çalışma, doğanın sunduğu hizmetlerin değerini küresel GSYH\'nin üzerinde bir tutar olarak tahmin etmiş ve ekosistem hizmetlerinin ekonomik değerlemesini tartışmaya açmıştır.'),
  ('\'Zayıf sürdürülebilirlik\' görüşü doğal sermaye ile beşerî sermaye arasında nasıl bir ilişki varsayar?', 'Doğal sermayenin ikame edilebileceğini', ['Doğal sermayenin hiçbir zaman ikame edilemeyeceğini', 'Beşerî sermayenin değersiz olduğunu', 'Doğal sermayenin yalnızca devlet tarafından yönetilmesi gerektiğini'], 'Zayıf sürdürülebilirlik, toplam sermaye stokunun korunmasını yeterli sayar; güçlü sürdürülebilirlik ise doğal sermayenin ayrı korunmasını ister.'),
  ('Nelson ve Winter\'ın 1982\'de ortaya koyduğu evrimci iktisat kuramında firmaların davranışı nasıl açıklanır?', 'Rutinler ve piyasa seçilimiyle', ['Her zaman en yüksek kârı hesaplayarak', 'Devletin planına uyarak', 'Yalnızca fiyat sinyalini izleyerek'], 'Firmalar karar kuralları olan rutinlerle davranır; piyasa başarısız rutinleri seçip eler, böylece biyolojik evrime benzer bir süreç doğar.'),
  ('W. Brian Arthur\'un \'artan getiriler ve kilitlenme\' (lock-in) fikri neyi açıklar?', 'Erken küçük olayların teknolojiyi kilitlemesi', ['Her teknolojinin zamanla azalan getiri sağlamasını', 'Piyasanın her zaman en iyi teknolojiyi seçmesini', 'Teknolojilerin hiç yayılmamasını'], 'Kullanıcı sayısı arttıkça teknolojinin değeri yükselirse, rastlantısal erken üstünlük kalıcı hâle gelebilir ve daha iyi alternatifler piyasaya giremeyebilir.'),
  ('Modern Parasal Teori (MMT) hükümet harcamalarının sınırı olarak neyi gösterir?', 'Enflasyon ve kaynak sınırlarını', ['Vergi gelirlerinin tam eşitliğini', 'Altın rezervlerini', 'Dış ticaret fazlasını'], 'MMT\'ye göre kendi para birimini çıkaran hükümet borcunu o para birimiyle ödeyebilir; asıl kısıt reel kaynaklar ve enflasyondur, vergi geliri değil.'),
  ('Büyümeme (degrowth) hareketinin temel iddiası nedir?', 'Zengin ülkelerin kaynak kullanımının küçülmesi', ['Tüm ülkelerin üretimini sürekli artırması gerektiği', 'Teknolojinin her sorunu çözeceği', 'Dış ticaretin tümüyle serbest olması gerektiği'], 'Latouche ve Kallis gibi yazarlar, ekolojik sınırlar ve yaşam kalitesi gerekçesiyle büyümeye dayalı kalkınma yerine kaynak kullanımının azaltılmasını savunur.'),
  ('Santa Fe Enstitüsü\'nde 1980\'lerde gelişen karmaşıklık iktisadı hangi varsayımı sorgular?', 'Denge ve temsilî aktör varsayımını', ['Ekonominin hiç veri üretmediği varsayımını', 'Tüm piyasaların devlet elinde olduğu varsayımını', 'Para kullanımının gereksiz olduğu varsayımını'], 'Karmaşıklık yaklaşımı, ekonomiyi birbiriyle etkileşen çok sayıda uyumlu aktörün dinamik, dengeden uzak sistemi olarak ele alır.'),
  ('Samuelson\'ın 1938\'de ortaya koyduğu \'ortaya çıkan tercih\' (revealed preference) yaklaşımı neyi varsayar?', 'Tercihlerin gözlenen seçimlerden çıkarılacağını', ['Tercihlerin yalnızca anketlerle öğrenilebileceğini', 'Faydanın doğrudan ölçülebildiğini', 'Seçimlerin rastgele yapıldığını'], 'Samuelson, tüketici kuramını gözlemlenemeyen faydaya değil piyasadaki seçimlere dayandırarak kuramı davranışçı bir temele oturtmuştur.'),
  ('Karl Popper\'ın \'yanlışlanabilirlik\' ölçütü iktisat kuramlarına uygulandığında ne anlama gelir?', 'Veriyle çelişebilecek öngörü üretmesi', ['Kuramın her koşulda doğru olduğunun kanıtlanması gerektiği', 'Kuramın yalnızca felsefi dille ifade edilmesi gerektiği', 'Kuramın hiçbir sınanamaz önerme içermemesi gerektiği'], 'Popper\'a göre bilimsel kuram yanlış çıkabilecek öngörüler yapmalıdır; Blaug gibi yazarlar iktisatta bu ölçütün önemini vurgulamıştır.'),
  ('Imre Lakatos\'un \'bilimsel araştırma programı\' kavramında \'sert çekirdek\' neyi ifade eder?', 'Tartışılmayan temel varsayımları', ['Programın kullandığı bütün istatistik verilerini', 'Programa karşı çıkan tüm görüşleri', 'Programın yalnızca ilk yayımlandığı kitabı'], 'Lakatos\'a göre sert çekirdek korunur, koruyucu kuşak yardımcı varsayımlar anomalilere karşı değiştirilir; neoklasik iktisatta rasyonellik gibi varsayımlar bu çekirdeğe örnek gösterilir.'),
  ('Thomas Kuhn\'un \'paradigma\' kavramı iktisat tarihinde en çok hangi gelişmeye uygulanmıştır?', 'Keynesyen devrim gibi köklü yaklaşım değişikliklerine', ['Fiyatların küçük günlük oynamalarına', 'Vergi oranlarındaki yıllık ayarlamalara', 'Bankaların faiz tabelalarındaki değişikliklere'], 'Marjinalist devrim ve Keynesyen devrim gibi olaylar Kuhncu paradigma değişimleri olarak yorumlanmış; ancak iktisatta bunun uygunluğu tartışmalıdır.'),
  ('Deirdre McCloskey\'in 1983 tarihli \'İktisadın Retoriği\' makalesi neyi savunur?', 'İktisatçıların da ikna anlatısı kullandığını', ['İktisatçıların hiç anlatı kullanmadığını', 'İktisadın yalnızca matematiksel bir dil olduğunu', 'İktisatta hiçbir tartışma bulunmadığını'], 'McCloskey, iktisat yazılarının da retorik araçlarla ikna ettiğini ve \'bilimsel yöntem\' söyleminin de bir retorik olduğunu savunmuştur.'),
  ('John Neville Keynes\'in \'Siyasal İktisadın Kapsamı ve Yöntemi\' (1891) eserindeki üçlü ayrım nedir?', 'Pozitif bilim, normatif bilim ve sanat', ['Mikro, makro ve ekonometri', 'Para, maliye ve ticaret', 'Klasik, marjinalist ve kurumsal'], 'J. N. Keynes iktisadın \'olanı\' inceleyen pozitif, \'olması gerekeni\' inceleyen normatif ve politika uygulayan \'sanat\' boyutları olduğunu belirtmiştir.'),
  ('Pozitif ile normatif iktisat arasındaki ayrımı destekleyen \'Hume giyotini\' ne söyler?', 'Olandan olması gereken çıkmaz', ['\'Olması gereken\'in her zaman \'olan\'a eşit olduğunu', 'Her pozitif önermenin ahlaki olduğunu', 'Hiçbir normatif önermenin yapılamayacağını'], 'Hume\'a göre olgu önermelerinden tek başına değer yargısı çıkarılamaz; iktisatta bu, bilimsel çözümleme ile politika önerisini ayırma gerekçesi olarak kullanılır.'),
  ('Duhem-Quine tezi iktisadi kuramların sınanmasında hangi zorluğu gösterir?', 'Kuramın yardımcı varsayımlarla sınanması', ['Hiçbir kuramın sınanamayacağını', 'Veri bulunamadığını', 'Kuramların hep doğru çıktığını'], 'Veri kuramla çelişirse sorun yardımcı varsayımlarda olabilir; bu yüzden iktisatta yanlışlama kesin değil, belirsiz kalır.'),
  ('\'Kendilerini her türlü entelektüel etkiden bağımsız sanan pratik insanlar, çoğu zaman ölmüş bir iktisatçının kölesidir\' sözü kime aittir?', 'John Maynard Keynes', ['Milton Friedman', 'Friedrich Hayek', 'Adam Smith'], 'Keynes, Genel Teori\'nin son bölümünde iktisatçıların ve siyaset felsefecilerinin fikirlerinin sanıldığından daha güçlü olduğunu belirtmiştir.'),
  ('Adam Smith\'in \'aynı meslekten insanlar eğlence için bile bir araya gelseler konuşma kamuoyuna karşı bir komploya döner\' sözü neyi eleştirir?', 'Tüccarların fiyat anlaşması eğilimini', ['Serbest ticareti yasaklama eğilimini', 'Devlet bütçesinin açık verme eğilimini', 'İşçilerin ücret talebi artırma eğilimini'], 'Smith, aynı işi yapanların fiyat artırmak için gizli anlaşma yapma eğilimini vurgulamış; yasaların bu toplantıları teşvik etmemesi gerektiğini belirtmiştir.'),
  ('Paul Samuelson\'ın 1947\'de yayımlanan, iktisat kuramını matematiksel dille yeniden kurduğu kitap hangisidir?', 'İktisadi Çözümlemenin Temelleri', ['İktisadın İlkeleri ve Matematik', 'Genel Denge ve Büyüme Kuramı', 'Kamu Maliyesi Kuramı'], '\'Foundations of Economic Analysis\', denge ve istikrar analizini matematiksel yöntemle kurarak sonraki iktisat eğitiminin dilini belirlemiştir.'),
  ('19. yüzyılda Para Okulu (Currency School) ile Bankacılık Okulu (Banking School) arasındaki temel tartışma neydi?', 'Banknotun katı altın kuralına bağlanması', ['Gümrük vergilerinin artırılıp azaltılması', 'Köleliğin kaldırılması', 'Toprak vergisinin oranı'], 'Para Okulu banknotun altın stokuna sıkı bağlanmasını, Bankacılık Okulu ise ticaretin ihtiyacına esnek uyumu savunmuştur.'),
  ('Adam Smith\'in \'gerçek senetler doktrini\' bankaların nasıl davranmasını önerir?', 'Gerçek ticari senetlere kredi vermesini', ['Spekülatif amaçlı kredileri öncelemesini', 'Bütün kredileri devlet garantisine bağlamasını', 'Altın dışındaki teminatı reddetmesini'], 'Doktrine göre banknot arzı, gerçek mal ticaretini finanse eden kısa vadeli senetlerle sınırlı kalırsa fiyatlar istikrarını korur.'),
  ('Georg Friedrich Knapp\'ın 1905 tarihli \'Paranın Devlet Kuramı\' neyi savunur?', 'Değerinin devletin ödeme kabulünden geldiğini', ['Paranın değerinin yalnızca altın içeriğinden geldiğini', 'Paranın değerinin takastan doğduğunu', 'Paranın değerinin dış ticaretle belirlendiğini'], 'Knapp\'a göre devlet yasal olarak neyi vergi ödemesinde kabul ediyorsa o şey para olur; bu görüş MMT\'nin kökenlerinden biridir.'),
  ('Carl Menger\'in paranın kökeni üzerine açıklaması nedir?', 'En kolay satılan malın değişim aracı olması', ['Para, bir hükümdarın kararnamesiyle icat edilmiştir', 'Para, dinî törenlerden doğmuştur', 'Para, bankaların kuruluşuyla ortaya çıkmıştır'], 'Menger, bireylerin takas güçlüğünü aşmak için en kolay elden çıkarılabilir mala yönelmesiyle paranın kendiliğinden ortaya çıktığını anlatır.'),
  ('A. Mitchell-Innes\'in 1913 \'kredi kuramı\' paranın doğasını nasıl açıklar?', 'Para borç-alacak ilişkisidir', ['Para her zaman altın veya gümüştür', 'Para, devletin altın stokuna eşit bir sayıdır', 'Para, yalnızca takasın aracıdır'], 'Mitchell-Innes, paranın çıkış noktasının takas değil kredi (borç) ilişkisi olduğunu savunarak metalist anlayıştan ayrılır.'),
  ('Tooke\'un \'Fiyatlar Tarihi\' çalışmaları ile Bankacılık Okulu\'nda öne çıkan görüş nedir?', 'Talep ve üretim koşulları belirleyicidir', ['Fiyatlar tümüyle banknot miktarına eşittir', 'Fiyatlar hiçbir zaman değişmez', 'Fiyatlar yalnızca altın madeninden belirlenir'], 'Tooke, para miktarını fiyatların nedeni sayan görüşe karşı çıkmış; banknotun ticaretin ihtiyaca göre uyum sağladığını savunmuştur.'),
  ('Frank Ramsey\'in 1927 tarihli optimal mal vergisi kuralı hangi sonuca varır?', 'Esnekliği düşük mala yüksek vergi', ['Talebi esnek mallara daha yüksek vergi konması', 'Tüm mallara aynı oranda vergi konması', 'Lüks mallardan hiç vergi alınmaması'], 'Ramsey kuralına göre toplam verimlilik kaybını en azaltmak için vergi oranları talep esnekliğiyle ters orantılı olmalıdır.'),
  ('James Mirrlees\'in 1971 tarihli optimal gelir vergisi çalışması hangi ödünleşmeyi ele alır?', 'Yeniden dağıtım ile çalışma teşviki', ['Dış ticaret açığı ile cari fazla arasındaki ödünleşmeyi', 'Para arzı ile faiz arasındaki ödünleşmeyi', 'Tarım ile sanayi arasındaki ödünleşmeyi'], 'Mirrlees, yüksek marjinal vergilerin eşitliği artırırken çalışma teşviğini azaltabileceğini formüle etmiş; 1996\'da Nobel Ödülü almıştır.'),
  ('Arthur Okun\'un \'delikli kova\' (leaky bucket) benzetmesi neyi anlatır?', 'Aktarımın bir kısmının kaybolmasını', ['Gelirin tümünün kaynağına eksiksiz ulaşmasını', 'Vergilerin hiç kayba uğramamasını', 'Kamu harcamalarının tümüyle enflasyona dönüşmesini'], 'Okun\'a göre yeniden dağıtımın bir bedeli vardır: yönetim maliyetleri ve çalışma teşviklerinin azalması nedeniyle aktarılan paranın bir bölümü kaybolur.'),
  ('Henri Theil\'in adıyla anılan eşitsizlik endeksinin ayırt edici özelliği nedir?', 'Gruplar içi ve arası bileşenlere ayrışması', ['Yalnızca tek bir gruba uygulanabilmesi', 'Hiç veri gerektirmemesi', 'Yalnızca servet verisiyle çalışması'], 'Theil endeksi bilgi kuramından türetilmiştir ve bölge, cinsiyet gibi gruplar içindeki ve arasındaki farkların toplam eşitsizliğe katkısını ayırır.'),
  ('Bowley yasası ve Cobb-Douglas çalışmaları emeğin gelirdeki payı hakkında hangi gözlemi içerir?', 'Emek payının uzun dönemde sabit kalması', ['Emeğin payının hızla sıfıra indiğini', 'Emeğin payının her yıl ikiye katlandığını', 'Emeğin payının hiçbir ülkede ölçülemediğini'], 'Bowley ve sonraki çalışmalar, ulusal gelirin yaklaşık üçte ikisinin emeğe gittiği örüntüsünü bulmuş; Kaldor\'un stilize olgularından biri olarak sayılır.'),
  ('Alan Krueger\'ın \'Büyük Gatsby Eğrisi\' neyi gösterir?', 'Eşitsizlikle hareketliliğin ters ilişkisini', ['Gelir eşitsizliği yüksek ülkelerde hareketliliğin de yüksek olduğunu', 'Eşitsizliğin hareketlilikle hiç ilişkili olmadığını', 'Eşitsizliğin yalnızca mevsimsel olduğunu'], 'Eğri, ülkeler arası verilerle babanın geliri ile oğulun geliri arasındaki bağın eşitsizlik arttıkça güçlendiğini gösterir.'),
  ('Thomas Piketty ve Emmanuel Saez\'in \'en üst gelirler\' çalışmalarında kullanılan başlıca veri kaynağı nedir?', 'Uzun dönemli vergi kayıtları', ['Tüketici güven anketleri', 'Dış ticaret istatistikleri', 'Banka faiz tabloları'], 'Piketty ve Saez, gelir vergisi beyannamelerini kullanarak yüzde 1 ve daha üst dilimlerin gelir paylarındaki uzun dönem değişimi ölçmüşlerdir.'),
  ('Joseph Stiglitz\'in 2012 tarihli \'Eşitsizliğin Bedeli\' kitabında öne sürdüğü temel görüş nedir?', 'Eşitsizliğin büyümeyi ve demokrasiyi zayıflattığı', ['Eşitsizliğin her zaman büyümeyi hızlandırdığı', 'Eşitsizliğin ölçülemeyeceği', 'Eşitsizliğin yalnızca doğal sonuçlar olduğu'], 'Stiglitz, tekel ve rant gücü ile siyasi etkinin eşitsizliği artırdığını; bunun talebi ve toplumsal güveni aşındırdığını savunur.'),
  ('Anthony Atkinson\'ın 2015 tarihli \'Eşitsizlik: Ne Yapılabilir?\' kitabı hangi tür öneriler içerir?', 'Çok yönlü vergi ve sosyal politika önerileri', ['Yalnızca altın standardına dönüş', 'Yalnızca tüm vergilerin kaldırılması', 'Yalnızca merkez bankası faiz artırımı'], 'Atkinson, teknolojiyi, rekabeti, vergi sistemini ve sosyal güvenliği kapsayan on beş öneri sunarak eşitsizliğin azaltılabileceğini savunmuştur.'),
  ('Simon Kuznets\'in 1955 tarihli çalışmasının önemli yöntemsel zayıflığı nedir?', 'Sınırlı kesit verisine dayanması', ['Hiç veri kullanmaması', 'Tüm dünya verisini eksiksiz kullanması', 'Yalnızca tarımı incelemesi'], 'Kuznets hipotezi başlangıçta az sayıda ülkenin sınırlı verisine dayanıyordu; sonraki çalışmalar ters-U ilişkisinin evrensel olmadığını göstermiştir.'),
  ('Freiburg Okulu\'nun kurucularından Walter Eucken\'in iktisat politikası anlayışının temel ilkesi nedir?', 'Rekabeti koruyan düzen çerçevesi', ['Devletin üretimi doğrudan yönetmesi', 'Devletin ekonomiden tümüyle çekilmesi', 'Devletin fiyatları tek tek belirlemesi'], 'Eucken\'e göre devlet piyasa süreçlerini yönetmez, rekabetin işleyeceği kuralları ve çerçeveyi (ordo) oluşturur.'),
  ('\'Neoliberalizm\' terimi ilk kez 1938\'de hangi toplantıda yaygın biçimde kullanılmıştır?', 'Paris\'teki Lippmann Kolokyumu', ['Bretton Woods Konferansı', 'Cenova Konferansı', 'Londra Ekonomi Konferansı'], 'Alexander Rüstow gibi katılımcılar, klasik laissez-faire\'den farklı, devletin rekabet düzenini güvence altına aldığı yeni bir liberalizm için bu terimi önermişlerdir.'),
  ('Wilhelm Röpke\'nin \'üçüncü yol\' anlayışı neyi savunur?', 'Kolektivizm ve laissez-faire dışında üçüncü yol', ['Tümüyle devlet planlamasını', 'Tümüyle denetimsiz piyasayı', 'Sendikasız serbest ticareti'], 'Röpke, piyasa ekonomisinin ahlaki ve toplumsal temellerinin korunmasını, sanayi toplumunda aşırı yığılmanın sınırlanmasını savunmuştur.'),
  ('Alman ordoliberalizmi tekeller konusunda hangi tutumu benimsemiştir?', 'Rekabeti koruyan güçlü kartel yasası', ['Tekelleri teşvik eden ulusal şampiyon politikası', 'Tekellerin devletleştirilmesini yasaklama', 'Tekellerin vergi muafiyeti'], 'Ordoliberallere göre özel iktisadi güç de bir tehdittir; bu nedenle 1957\'de çıkan Rekabet Kısıtlamalarına Karşı Yasa ve Kartel Dairesi bu anlayıştan doğmuştur.'),
  ('Almanya\'da Bundesbank\'ın (Merkez Bankası) bağımsızlığı kurumsal olarak hangi anlayışla bağdaşır?', 'Fiyat istikrarının siyasetten korunması fikriyle', ['Hükümetin para basımını belirleyen merkezi plan fikriyle', 'Kâğıt paranın kaldırılması fikriyle', 'Altın standardının yasaklanması fikriyle'], 'Alman ordoliberalleri para istikrarının rekabet düzeninin temel koşulu olduğunu düşünmüş; bu görüş 1957 Bundesbank Yasası\'na yansımıştır.'),
  ('Ordoliberallerin Keynesyen talep yönetimine yaklaşımı genel olarak nasıldır?', 'Bütçe disiplini lehine kuşkuyla', ['Her yıl bütçe açığı vermeyi hedeflerler', 'Merkez bankasının bütün kontrolünü hükümete verirler', 'Kamu harcamasını sınırsızca artırırlar'], 'Alman ordoliberal gelenekte takdire dayalı ince ayar yerine kural, bütçe dengesi ve fiyat istikrarı öne çıkar.'),
  ('Aşağıdakilerden hangisi John Williamson\'ın Washington Mutabakatı\'nın ilk listesinde yer almaz?', 'Sermaye hareketlerinin tümüyle serbestliği', ['Mali disiplin', 'Ticaretin serbestleştirilmesi', 'Kamu işletmelerinin özelleştirilmesi'], 'Williamson\'ın 1989 listesinde doğrudan yabancı yatırıma açıklık vardı ancak kısa vadeli sermaye hareketlerinin tümüyle serbestleştirilmesi yer almıyordu.'),
  ('David Harvey\'in \'Neoliberalizmin Kısa Tarihi\' (2005) kitabı neoliberalizmi nasıl tanımlar?', 'Sınıf iktisadını yeniden kurma projesi olarak', ['Merkezî planlamanın zaferi olarak', 'Köylülüğün yükselişi olarak', 'Toprak reformunun sonucu olarak'], 'Harvey\'e göre neoliberalizm, serbest piyasa söylemiyle sermaye sahiplerinin gelir ve güç payını artıran bir siyasal-ekonomik projedir.'),
  ('Washington Mutabakatı sonrasında \'Washington Sonrası Mutabakat\' fikri hangi yöne işaret eder?', 'Kurumlar ve sosyal güvenliğin de önemsenmesine', ['Yalnızca özelleştirmeye ve fiyat serbestliğine', 'Yalnızca altın standardına', 'Yalnızca askeri harcamalara'], 'Stiglitz, Rodrik ve diğerleri, ilk reçetenin kurumsal altyapı, yoksulluk ve istihdam sorunlarını ihmal ettiğini savunarak daha geniş bir yaklaşım önermiştir.'),
  ('Neoliberal politika paketlerinin \'sermaye hesabı serbestleştirmesi\' bileşeni kriz dönemlerinde neden eleştirilmiştir?', 'Ani çıkışlar krizleri hızlandırabildiği için', ['Sermaye girişlerini tümüyle durdurduğu için', 'Faizleri sıfıra indirdiği için', 'Üretimi doğrudan kamulaştırdığı için'], '1990\'lardaki Meksika, Doğu Asya ve Rusya krizleri, kısa vadeli sermaye hareketlerinin istikrarsızlaştırıcı etkisi tartışmasını yoğunlaştırmıştır.'),
  ('1970\'lerde Şili\'de uygulanan piyasa reformlarının Latin Amerika\'da neoliberal politikaların yayılmasına etkisi nedir?', 'Bölgede bir model ve tartışma örneği olması', ['Bölgede tüm özelleştirmelerin yasaklanması', 'Merkezî planlamanın bölgeye yayılması', 'Dış borçların silinmesi'], 'Şili deneyimi, Chicago\'da eğitim almış iktisatçıların reformlarıyla piyasa serbestliğinin hızla uygulandığı ilk örneklerden biri olarak hem savunulmuş hem eleştirilmiştir.'),
  ('Neoliberalizm eleştirilerinde sıkça öne sürülen \'rant kollama\' savı neyi söyler?', 'Büyük şirketlerin siyasal güçle ayrıcalık kazanması', ['Rant kollamanın serbestleşmeyle tümüyle ortadan kalktığını', 'Rantın yalnızca tarımda görüldüğünü', 'Rant kollamanın hiçbir zaman ölçülemediğini'], 'Eleştirmenlere göre \'serbest piyasa\' retoriği, düzenlemeleri yeniden biçimlendirerek büyük sermaye lehine rant yaratabilir.'),
  ('Clive Granger\'ın \'nedensellik\' kavramı iktisat zaman serilerinde neyi ifade eder?', 'Geçmişin geleceği tahmine ek bilgi vermesini', ['Bir değişkenin diğerini doğrudan fiziksel olarak üretmesini', 'İki değişkenin hiçbir zaman bağlantılı olmamasını', 'Bir değişkenin yalnızca kendi geçmişine bağlı olmasını'], 'Granger nedenselliği tahmin içeriğine dayanır; gerçek nedensellik anlamına gelmez ama zaman serisi analizinde yaygın kullanılır.'),
  ('Granger ve Engle\'ın eş bütünleşme (cointegration) çalışması hangi sorunu çözer?', 'Durağan olmayan serilerin uzun dönem ilişkisini', ['Verilerin hiç toplanamamasını', 'Faiz oranlarının sıfıra inmesini', 'Vergi gelirlerinin hesaplanmasını'], 'Kendi başına durağan olmayan iki seri bir doğrusal bileşimde durağansa uzun dönemde denge ilişkisi taşır; sahte regresyon sorununu da aşar.'),
];
